  function languageCookie() {
    try {
      const match = document.cookie.match(/(?:^|;\s*)roomgrid_language=([^;]+)/u);
      return match ? decodeURIComponent(match[1]) : '';
    } catch (_) { return ''; }
  }

  function detectLang() {
    const stored = localStorage.getItem(LANG_KEY);
    if (ROOMGRID_LANGUAGES.includes(stored)) return stored;
    const cookieLanguage = languageCookie();
    if (ROOMGRID_LANGUAGES.includes(cookieLanguage)) return cookieLanguage;
    const hostLanguage = String(location.hostname || '').toLocaleLowerCase().split('.')[0];
    if (ROOMGRID_LANGUAGES.includes(hostLanguage)) return hostLanguage;
    const browserLangs = [
      ...(Array.isArray(navigator.languages) ? navigator.languages : []),
      navigator.language,
      navigator.userLanguage,
    ].filter(Boolean).map(v => String(v).toLowerCase());
    const primary = browserLangs.find(v => /^(?:de|en|es|pt|fr|it|ru|ja|pl|ro|nl|tr)/u.test(v)) || '';
    const detected = ROOMGRID_LANGUAGES.find(language => primary.startsWith(language));
    if (detected) return detected;
    return 'en';
  }
  let LANG = detectLang();
  const roomGridPatternCache = new Map();
  const roomGridLocalizedValueCache = new Map();
  function isAlreadyLocalizedText(text, language) {
    if (!roomGridLocalizedValueCache.has(language)) {
      const translations = ROOMGRID_LATIN_TRANSLATIONS[language] || {};
      roomGridLocalizedValueCache.set(language, new Set([
        ...Object.values(translations.phrases || {}),
        ...Object.values(translations.visible || {}),
      ]));
    }
    return roomGridLocalizedValueCache.get(language).has(text);
  }
  function translatedPatternText(text, language) {
    const patterns = ROOMGRID_LATIN_TRANSLATIONS[language]?.patterns || {};
    if (!Object.keys(patterns).length) return '';
    if (!roomGridPatternCache.has(language)) {
      const compiled = Object.entries(patterns).map(([source, target]) => {
        if (source === '[[ROOMGRID_VALUE_0]] model[[ROOMGRID_VALUE_1]]') {
          return { regex: /^(.+?) model(s?)$/u, target, captures: [0, 1] };
        }
        const captures = [];
        let cursor = 0;
        let expression = '^';
        const marker = /\[\[ROOMGRID_VALUE_(\d+)\]\]/gu;
        for (const match of source.matchAll(marker)) {
          expression += source.slice(cursor, match.index).replace(/[.*+?^${}()|[\]\\]/gu, '\\$&');
          expression += '([\\s\\S]*?)';
          captures.push(Number(match[1]));
          cursor = match.index + match[0].length;
        }
        expression += `${source.slice(cursor).replace(/[.*+?^${}()|[\]\\]/gu, '\\$&')}$`;
        return { regex: new RegExp(expression, 'u'), target, captures };
      });
      roomGridPatternCache.set(language, compiled);
    }
    for (const pattern of roomGridPatternCache.get(language)) {
      const match = text.match(pattern.regex);
      if (!match) continue;
      const values = {};
      pattern.captures.forEach((index, captureIndex) => { values[index] = match[captureIndex + 1]; });
      return pattern.target.replace(/\[\[ROOMGRID_VALUE_(\d+)\]\]/gu, (_, index) => {
        const value = values[Number(index)] ?? '';
        return ROOMGRID_LATIN_TRANSLATIONS[language]?.phrases?.[value]
          || ROOMGRID_LATIN_TRANSLATIONS[language]?.visible?.[value]
          || translatedPatternText(value, language)
          || value;
      });
    }
    return '';
  }
  const latinText = (value, language = LANG) => {
    const text = String(value ?? '');
    if (text === 'RoomGrid') return text;
    const translations = ROOMGRID_LATIN_TRANSLATIONS[language] || {};
    if (isAlreadyLocalizedText(text, language)) return text;
    return translations.visible?.[text] || translations.phrases?.[text] || translatedPatternText(text, language) || text;
  };
  const camclientUiText = value => String(value ?? '').replaceAll('RoomGrid', 'Camclient');
  roomGridUiText = value => camclientUiText(latinText(value));
  const t = (key, ...args) => {
    const v = (I18N[LANG] && I18N[LANG][key]) ?? I18N.en[key] ?? key;
    return camclientUiText(typeof v === 'function' ? v(...args) : v);
  };
  const tx = (zh, en, de = en, es, pt) => {
    if (LANG === 'de') return camclientUiText(de);
    if (LANG === 'es') return camclientUiText(es ?? latinText(en, 'es'));
    if (LANG === 'pt') return camclientUiText(pt ?? latinText(en, 'pt'));
    if (['fr', 'it', 'ru', 'ja', 'pl', 'ro', 'nl', 'tr'].includes(LANG)) return camclientUiText(latinText(en, LANG));
    return camclientUiText(en);
  };

  function requestValue(request) {
    return new Promise((resolve, reject) => { request.onsuccess = () => resolve(request.result); request.onerror = () => reject(request.error || new Error('IndexedDB request failed')); });
  }

  async function dumpLanguageDatabase(name) {
    if (!window.indexedDB?.databases) return null;
    const databases = await indexedDB.databases();
    if (!databases.some(database => database.name === name)) return null;
    const db = await requestValue(indexedDB.open(name));
    try {
      const names = [...db.objectStoreNames];
      if (!names.length) return null;
      const transaction = db.transaction(names, 'readonly');
      const stores = [];
      for (const storeName of names) {
        const store = transaction.objectStore(storeName);
        const indexes = [...store.indexNames].map(indexName => {
          const index = store.index(indexName);
          return { name: index.name, keyPath: index.keyPath, unique: index.unique, multiEntry: index.multiEntry };
        });
        stores.push({ name: storeName, keyPath: store.keyPath, autoIncrement: store.autoIncrement, indexes, rows: await requestValue(store.getAll()) });
      }
      return { name, version: db.version, stores };
    } finally { db.close(); }
  }

  async function restoreLanguageDatabase(snapshot) {
    if (!snapshot?.name || !Array.isArray(snapshot.stores)) return;
    const known = window.indexedDB?.databases ? await indexedDB.databases() : [];
    const exists = known.some(database => database.name === snapshot.name);
    const request = exists ? indexedDB.open(snapshot.name) : indexedDB.open(snapshot.name, Math.max(1, Number(snapshot.version) || 1));
    request.onupgradeneeded = () => {
      const db = request.result;
      snapshot.stores.forEach(schema => {
        const store = db.objectStoreNames.contains(schema.name)
          ? request.transaction.objectStore(schema.name)
          : db.createObjectStore(schema.name, { keyPath: schema.keyPath ?? null, autoIncrement: !!schema.autoIncrement });
        (schema.indexes || []).forEach(index => { if (!store.indexNames.contains(index.name)) store.createIndex(index.name, index.keyPath, { unique: !!index.unique, multiEntry: !!index.multiEntry }); });
      });
    };
    const db = await requestValue(request);
    try {
      const names = snapshot.stores.map(store => store.name).filter(name => db.objectStoreNames.contains(name));
      if (!names.length) return;
      const transaction = db.transaction(names, 'readwrite');
      snapshot.stores.forEach(snapshotStore => {
        if (!names.includes(snapshotStore.name)) return;
        const store = transaction.objectStore(snapshotStore.name);
        (snapshotStore.rows || []).forEach(row => { try { store.put(row); } catch (_) {} });
      });
      await new Promise((resolve, reject) => { transaction.oncomplete = resolve; transaction.onerror = () => reject(transaction.error || new Error('IndexedDB restore failed')); transaction.onabort = () => reject(transaction.error || new Error('IndexedDB restore aborted')); });
    } finally { db.close(); }
  }

  async function prepareRoomGridLanguageTransfer(language) {
    const nonce = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
    const local = {};
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (key && /^(?:ryujo_|multicam_|roomgrid_)/u.test(key)) local[key] = localStorage.getItem(key);
    }
    const databases = [];
    for (const name of ROOMGRID_LANGUAGE_DATABASES) {
      try { const snapshot = await dumpLanguageDatabase(name); if (snapshot) databases.push(snapshot); } catch (_) {}
    }
    const serialized = JSON.stringify({ schema: 1, nonce, language, createdAt: Date.now(), local, databases });
    if (!window.GM?.setValue) throw new Error('Shared userscript storage is unavailable');
    await GM.setValue(ROOMGRID_LANGUAGE_TRANSFER_KEY, serialized);
    return nonce;
  }

  async function restoreRoomGridLanguageTransfer() {
    const url = new URL(location.href);
    const nonce = url.searchParams.get('roomgrid_language_transfer');
    if (!nonce) return false;
    let serialized = '';
    try { if (window.GM?.getValue) serialized = await GM.getValue(ROOMGRID_LANGUAGE_TRANSFER_KEY, ''); } catch (_) {}
    try {
      const bundle = JSON.parse(serialized || '{}');
      if (bundle.nonce !== nonce || Date.now() - Number(bundle.createdAt || 0) > 10 * 60 * 1000) throw new Error('Language transfer expired');
      Object.entries(bundle.local || {}).forEach(([key, value]) => { if (/^(?:ryujo_|multicam_|roomgrid_)/u.test(key) && typeof value === 'string') localStorage.setItem(key, value); });
      localStorage.setItem(LANG_KEY, bundle.language);
      for (const database of bundle.databases || []) await restoreLanguageDatabase(database);
    } finally {
      try { if (window.GM?.deleteValue) await GM.deleteValue(ROOMGRID_LANGUAGE_TRANSFER_KEY); } catch (_) {}
      url.searchParams.delete('roomgrid_language_transfer');
      history.replaceState(history.state, '', url.toString());
    }
    return true;
  }

  function languageBusyOverlay(language) {
    const labels = {
      de: 'Sprache wird gewechselt … RoomGrid-Daten werden sicher übernommen.',
      en: 'Changing language… RoomGrid data is being transferred safely.',
      es: 'Cambiando el idioma… Los datos de RoomGrid se transferirán de forma segura.',
      pt: 'Alterando o idioma… Os dados do RoomGrid serão transferidos com segurança.',
      fr: 'Changement de langue… Les données RoomGrid sont transférées en toute sécurité.',
      it: 'Cambio della lingua… I dati di RoomGrid vengono trasferiti in modo sicuro.',
      ru: 'Смена языка… Данные RoomGrid безопасно переносятся.',
      ja: '言語を変更しています… RoomGridのデータを安全に引き継いでいます。',
      pl: 'Zmiana języka… Dane RoomGrid są bezpiecznie przenoszone.',
      ro: 'Se schimbă limba… Datele RoomGrid sunt păstrate în siguranță.',
      nl: 'Taal wijzigen… RoomGrid-gegevens worden veilig overgezet.',
      tr: 'Dil değiştiriliyor… RoomGrid verileri güvenle aktarılıyor.',
    };
    const overlay = document.createElement('div');
    overlay.dataset.roomgridLanguageBusy = '1';
    Object.assign(overlay.style, { position: 'fixed', inset: '0', zIndex: '2147483647', display: 'grid', placeItems: 'center', padding: '24px', color: '#fff', background: 'rgba(5,12,20,.92)', font: '800 15px/1.5 Inter,system-ui,sans-serif', textAlign: 'center' });
    overlay.textContent = labels[language] || labels.en;
    document.documentElement.appendChild(overlay);
    return overlay;
  }

  async function setLang(lang) {
    if (!ROOMGRID_LANGUAGES.includes(lang)) return;
    localStorage.setItem(LANG_KEY, lang);
    try { document.cookie = `${ROOMGRID_LANGUAGE_COOKIE}=${encodeURIComponent(lang)}; Path=/; Domain=.chaturbate.com; Max-Age=31536000; SameSite=Lax; Secure`; } catch (_) {}
    const targetHost = ROOMGRID_LANGUAGE_HOSTS[lang];
    if (!targetHost || location.hostname === targetHost) { location.reload(); return; }
    const overlay = languageBusyOverlay(lang);
    try {
      const nonce = await prepareRoomGridLanguageTransfer(lang);
      const target = new URL(location.href);
      target.hostname = targetHost;
      target.searchParams.set('roomgrid_language_transfer', nonce);
      location.assign(target.toString());
    } catch (error) {
      overlay.remove();
      alert(tx('无法安全准备语言切换。未离开当前页面。', 'The language switch could not be prepared safely. This page was not left.', 'Der Sprachwechsel konnte nicht sicher vorbereitet werden. Die aktuelle Seite wurde nicht verlassen.', 'No se pudo preparar el cambio de idioma de forma segura. No se abandonó esta página.', 'Não foi possível preparar a alteração de idioma com segurança. Esta página não foi fechada.'));
    }
  }

  function createLanguageSwitcher(className = '') {
    const languageHost = ROOMGRID_LANGUAGE_HOSTS[LANG];
    const hostAligned = !languageHost || languageHost === location.hostname;
    const nativeOption = (value, label) => {
      const option = document.createElement('option');
      option.value = value;
      option.selected = hostAligned && LANG === value;
      option.textContent = label;
      return option;
    };
    const choices = [];
    if (!hostAligned) {
      const alignLabels = {
        de: '🌐 DE · Website angleichen', en: '🌐 EN · Apply to website', es: '🌐 ES · Aplicar al sitio',
        pt: '🌐 PT · Aplicar ao site', fr: '🌐 FR · Appliquer au site', it: '🌐 IT · Applica al sito',
        ru: '🌐 RU · Применить к сайту', ja: '🌐 JA · サイトにも適用', pl: '🌐 PL · Zastosuj w witrynie',
        ro: '🌐 RO · Aplică pe site', nl: '🌐 NL · Op website toepassen', tr: '🌐 TR · Siteye uygula',
      };
      const align = document.createElement('option');
      align.value = '';
      align.selected = true;
      align.disabled = true;
      align.textContent = alignLabels[LANG] || alignLabels.en;
      choices.push(align);
    }
    choices.push(
      nativeOption('de', 'DE · Deutsch'),
      nativeOption('en', 'EN · English'),
      nativeOption('es', 'ES · Español'),
      nativeOption('pt', 'PT · Português'),
      nativeOption('fr', 'FR · Français'),
      nativeOption('it', 'IT · Italiano'),
      nativeOption('ru', 'RU · Русский'),
      nativeOption('ja', 'JA · 日本語'),
      nativeOption('pl', 'PL · Polski'),
      nativeOption('ro', 'RO · Română'),
      nativeOption('nl', 'NL · Nederlands'),
      nativeOption('tr', 'TR · Türkçe'),
    );
    const select = $('select', {
      class: `roomgrid-language-select ${className}`.trim(),
      dataset: { roomgridLanguageSelect: '1' },
      title: languageHost ? t('languageSwitcherTitle') : t('languageSwitcherLocalTitle'),
      ariaLabel: tx('语言', 'Language', 'Sprache', 'Idioma', 'Idioma'),
    }, choices);
    Object.assign(select.style, { minHeight: '34px', padding: '5px 8px', border: '1px solid currentColor', borderRadius: '6px', color: 'inherit', background: 'inherit', font: '800 11px/1 system-ui,sans-serif', cursor: 'pointer' });
    select.addEventListener('change', async () => { if (!select.value) return; select.disabled = true; await setLang(select.value); select.disabled = false; });
    return select;
  }
