    const responsiveId = baseSettings.responsiveAppearanceProfilesEnabled ? String(baseSettings.responsiveAppearanceProfiles?.[deviceKey]?.[pageKey] || '') : '';
    const profileId = responsiveId || (baseSettings.pageAppearanceProfilesEnabled ? String(baseSettings.pageAppearanceProfiles?.[pageKey] || '') : '');
    const pageProfile = profileId ? (baseSettings.appearanceProfiles || []).find(profile => profile.id === profileId) : null;
    const settings = pageProfile?.values ? { ...baseSettings, ...pageProfile.values } : baseSettings;
