  function createCommandPalette(store, actionSource = () => [], options = {}) {
    installSuiteExperienceStyles();
    let overlay = null;
    const getActions = () => {
      const actions = typeof actionSource === 'function' ? actionSource() : actionSource;
      const models = (store?.state?.rooms || []).map(room => ({
        id: `model:${room.id}`, title: room.id,
        detail: [room.notes, ...(room.localTags || [])].filter(Boolean).join(' · ') || tx('保存的模型', 'Saved model', 'Gespeichertes Model'),
        icon: room.lastStatus === 'online' ? '●' : '○', keywords: `${room.id} ${room.notes || ''} ${(room.localTags || []).join(' ')}`,
        run: () => options.onModel?.(room.id),
      }));
      return [...(Array.isArray(actions) ? actions : []), ...models].filter(item => item && typeof item.run === 'function');
    };
    const close = () => { overlay?.remove(); overlay = null; };
    const open = (initial = '') => {
      close();
      overlay = $('div', { class: 'rg-command-overlay', dataset: { roomgridCommand: '1' } });
      const input = $('input', { class: 'rg-command-search', type: 'search', value: initial, placeholder: tx('搜索模型、页面、工作区和命令…', 'Search models, pages, workspaces and commands…', 'Models, Seiten, Arbeitsbereiche und Befehle durchsuchen…'), autocomplete: 'off' });
      const results = $('div', { class: 'rg-command-results' });
      const panel = $('section', { class: 'rg-command', role: 'dialog', ariaModal: 'true' }, [input, results, $('div', { class: 'rg-command-foot' }, tx('输入以筛选 · Enter 执行 · Esc 关闭', 'Type to filter · Enter to run · Esc to close', 'Tippen zum Filtern · Enter ausführen · Esc schließen'))]);
      overlay.appendChild(panel);
      const render = () => {
        const terms = String(input.value || '').toLocaleLowerCase().split(/\s+/u).filter(Boolean);
        const items = getActions().filter(item => {
          const hay = `${item.title || ''} ${item.detail || ''} ${item.keywords || ''}`.toLocaleLowerCase();
          return terms.every(term => hay.includes(term));
        }).slice(0, 40);
        results.replaceChildren(...(items.length ? items.map((item, index) => $('button', {
          class: `rg-command-result${index === 0 ? ' active' : ''}`, type: 'button', onclick: () => { close(); item.run(); },
        }, [$('i', {}, item.icon || '›'), $('span', {}, [$('strong', {}, item.title || ''), $('small', {}, item.detail || '')]), item.shortcut ? $('kbd', {}, item.shortcut) : $('span')])) : [$('div', { style: { padding: '24px', textAlign: 'center', color: '#64748b' } }, tx('没有匹配项', 'No matches', 'Keine Treffer'))]));
      };
      input.addEventListener('input', render);
      input.addEventListener('keydown', event => {
        const buttons = [...results.querySelectorAll('.rg-command-result')];
        let active = Math.max(0, buttons.findIndex(button => button.classList.contains('active')));
        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
          event.preventDefault(); buttons[active]?.classList.remove('active'); active = (active + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % Math.max(1, buttons.length); buttons[active]?.classList.add('active'); buttons[active]?.scrollIntoView({ block: 'nearest' });
        } else if (event.key === 'Enter') { event.preventDefault(); buttons[active]?.click(); }
      });
      overlay.addEventListener('click', event => { if (event.target === overlay) close(); });
      render();
      document.body.appendChild(overlay);
      setTimeout(() => input.focus(), 0);
    };
    const onKey = event => {
      if (event.key === 'Escape' && overlay) { event.preventDefault(); close(); return; }
      const shortcuts = sanitizeShortcuts(store?.state?.settings?.shortcuts, defaultShortcuts());
      const pressed = shortcutFromEvent(event);
      if (pressed === shortcuts.commandPalette || pressed === shortcuts.globalSearch) {
        event.preventDefault();
        open();
      }
    };
    document.addEventListener('keydown', onKey, true);
    return { open, close, destroy() { document.removeEventListener('keydown', onKey, true); close(); } };
  }

  function createSuiteDataManager(store) {
    const sections = ['models', 'groups', 'workspaces', 'layouts', 'settings'];
    const exportData = (selected = sections) => {
      const include = new Set(selected);
      const state = store.state;
      const payload = { kind: SUITE_EXPORT_KIND, schema: 2, softwareVersion: META.version, dataVersion: state.dataVersion || 1, exportedAt: Date.now(), sensitive: include.has('models') || include.has('groups') || include.has('workspaces'), sections: [...include] };
      if (include.has('models')) payload.rooms = jsonClone(state.rooms, []);
      if (include.has('groups')) payload.groups = jsonClone(state.groups, []);
      if (include.has('workspaces')) payload.workspaces = jsonClone(state.workspaces, []);
      if (include.has('layouts')) payload.layoutTemplates = jsonClone(state.layoutTemplates, []);
      if (include.has('settings')) payload.settings = jsonClone(state.settings, {});
      return payload;
    };
    const sourceState = raw => raw?.kind === SUITE_EXPORT_KIND ? raw : raw?.state && typeof raw.state === 'object' ? raw.state : raw;
    const inspect = raw => {
      const source = sourceState(raw);
      if (!source || typeof source !== 'object' || Array.isArray(source)) throw new Error('invalid backup');
      const current = store.state;
      const basis = { ...defaultState(), ...source };
      if (source.groups === undefined) basis.groups = current.groups;
      if (source.settings === undefined) basis.settings = current.settings;
      if (source.workspaces === undefined) basis.workspaces = current.workspaces;
      if (source.layoutTemplates === undefined) basis.layoutTemplates = current.layoutTemplates;
      const imported = sanitizeState(basis);
      const changed = (incoming, existing, key = 'id') => incoming.filter(item => {
        const prior = existing.find(value => value[key] === item[key]);
        return prior && JSON.stringify(prior) !== JSON.stringify(item);
      }).length;
      return {
        raw: source,
        imported,
        sections: Array.isArray(raw?.sections) ? raw.sections.filter(section => sections.includes(section)) : sections.filter(section => source[section === 'models' ? 'rooms' : section === 'layouts' ? 'layoutTemplates' : section] !== undefined),
        counts: { models: imported.rooms.length, groups: imported.groups.filter(item => !item.system).length, workspaces: imported.workspaces.length, layouts: imported.layoutTemplates.length, settings: source.settings ? 1 : 0 },
        newItems: { models: imported.rooms.filter(item => !current.rooms.some(value => value.id === item.id)).length, groups: imported.groups.filter(item => !item.system && !current.groups.some(value => value.id === item.id)).length, workspaces: imported.workspaces.filter(item => !current.workspaces.some(value => value.id === item.id)).length, layouts: imported.layoutTemplates.filter(item => !current.layoutTemplates.some(value => value.id === item.id)).length },
        conflicts: { models: changed(imported.rooms, current.rooms), groups: changed(imported.groups.filter(item => !item.system), current.groups), workspaces: changed(imported.workspaces, current.workspaces), layouts: changed(imported.layoutTemplates, current.layoutTemplates) },
        sensitive: raw?.sensitive !== false && (imported.rooms.length > 0 || imported.workspaces.length > 0),
      };
    };
    const mergeList = (current, incoming, mergeItem = null) => {
      const map = new Map((current || []).map(item => [item.id, jsonClone(item, item)]));
      for (const item of incoming || []) {
        const previous = map.get(item.id);
        if (!previous) map.set(item.id, item);
        else if (mergeItem) map.set(item.id, mergeItem(previous, item));
        else if (Number(item.modifiedAt || item.addedAt || 0) >= Number(previous.modifiedAt || previous.addedAt || 0)) map.set(item.id, { ...previous, ...item });
      }
      return [...map.values()];
    };
    const apply = (review, selected = review.sections, strategy = 'merge') => {
      if (!review?.imported) throw new Error('preview required');
      const include = new Set(selected);
      backupCurrentConfig();
      const current = sanitizeState(store.state);
      const incoming = review.imported;
      const next = jsonClone(current, current);
      const choose = (key, section) => {
        if (!include.has(section)) return;
        next[key] = strategy === 'replace' ? jsonClone(incoming[key], []) : mergeList(next[key], incoming[key], key === 'rooms' ? mergeRoomRecords : null);
      };
      choose('rooms', 'models'); choose('groups', 'groups'); choose('workspaces', 'workspaces'); choose('layoutTemplates', 'layouts');
      if (include.has('settings')) next.settings = strategy === 'replace' ? jsonClone(incoming.settings, {}) : { ...next.settings, ...incoming.settings };
      const clean = sanitizeState(next);
      if (!Storage.save(clean)) throw new Error('save failed');
      store.replaceState(clean, 'all');
      return clean;
    };
    const exportCsv = rooms => {
      const quote = value => `"${String(value ?? '').replace(/"/gu, '""')}"`;
      const rows = [['username','status','favorite','following','watchlist','archived','rating','priority','last_online','notes','tags','groups']];
      const followed = store.state.settings.followedGroupId;
      for (const room of rooms || store.state.rooms) rows.push([room.id, room.lastStatus, roomInGroup(room, FAVORITE_GROUP_ID), followed ? roomInGroup(room, followed) : false, !!room.watchlist, !!room.archived, room.rating || 0, room.priority || 0, room.lastSeenOnline || 0, room.notes || '', (room.localTags || []).join('|'), getRoomGroups(room).join('|')]);
      return rows.map(row => row.map(quote).join(',')).join('\r\n');
    };
    const cleanupLegacy = () => { let count = 0; for (const key of LEGACY_STORE_KEYS) { try { if (localStorage.getItem(key) != null) { localStorage.removeItem(key); count++; } } catch (_) {} } return count; };
    return { sections, exportData, inspect, apply, exportCsv, cleanupLegacy };
  }

