    function findHeaderHost() {
      const candidates = [
        document.querySelector('[data-testid="header-nav-bar"]:not(.HeaderNavBar--hidden)'),
        document.querySelector('#desktop-spa-header nav:not(.HeaderNavBar--hidden)'),
        document.querySelector('#desktop-spa-header [data-testid="header-top-row"]'),
        document.querySelector('#desktop-spa-header [data-testid*="nav" i]'),
        document.querySelector('header [data-testid*="nav" i]'),
        document.querySelector('[role="banner"] nav'),
        document.querySelector('header nav'),
        document.querySelector('#desktop-spa-header'),
        document.querySelector('[data-testid="header"]'),
        document.querySelector('header'),
        document.querySelector('[role="banner"]'),
        document.querySelector('#header'),
        document.querySelector('body > nav'),
      ];
      return candidates.find(node => node?.isConnected && !node.closest('[data-roomgrid-native-hub]')) || null;
    }

    const NATIVE_CARD_SELECTOR = '[data-testid="room-card"],li.RoomCard,li.room_list_room,li.roomCard,article[data-username],li[data-username]';

    function customHomeGroups() {
      return (activeStore?.state?.groups || []).filter(group => group && !group.system && !group.archived);
    }

    function isHomepage() {
      return (location.pathname.replace(/\/+$/u, '') || '/') === '/';
    }

    function nativeCardId(card) {
      const direct = normalizeUsername(card?.getAttribute?.('data-username') || card?.getAttribute?.('data-room') || '');
      if (isLikelyUsername(direct)) return direct;
      const nested = card?.querySelector?.('[data-username],[data-room]');
      const nestedId = normalizeUsername(nested?.getAttribute?.('data-username') || nested?.getAttribute?.('data-room') || '');
      if (isLikelyUsername(nestedId)) return nestedId;
      for (const link of card?.querySelectorAll?.('a[href]') || []) {
        const id = roomIdFromHref(link.getAttribute('href'));
        if (id) return id;
      }
      return '';
    }

    function nativeRoomCards() {
      return [...document.querySelectorAll(NATIVE_CARD_SELECTOR)].filter(card => !card.parentElement?.closest?.(NATIVE_CARD_SELECTOR));
    }

    function selectedHomeGroupNames() {
      const selected = new Set(viewState.homeGroups);
      return customHomeGroups().filter(group => selected.has(group.id)).map(groupLabel);
    }

    function updateHomeFilterStatus() {
      const status = groupMenuPanel?.querySelector?.('.rgh-group-popover-status');
      if (!status) return;
      if (!viewState.homeGroups.length) status.textContent = tx('未启用分组筛选 · 显示所有模型。', 'No group filter active · all models are shown.', 'Kein Gruppenfilter aktiv · alle Models werden angezeigt.', 'No hay ningún filtro de grupo activo · se muestran todos los modelos.', 'Nenhum filtro de grupo ativo · todos os modelos são exibidos.');
      else status.textContent = tx(`${homeFilterStats.total} 个当前加载的模型中有 ${homeFilterStats.visible} 个可见。`, `${homeFilterStats.visible} of ${homeFilterStats.total} currently loaded models visible.`, `${homeFilterStats.visible} von ${homeFilterStats.total} aktuell geladenen Models sichtbar.`, `${homeFilterStats.visible} de ${homeFilterStats.total} modelos cargados visibles.`, `${homeFilterStats.visible} de ${homeFilterStats.total} modelos carregados visíveis.`);
    }

    function removeHomeFilterBanner() {
      homeFilterBanner?.remove();
      homeFilterBanner = null;
    }

    function updateHomeFilterBanner() {
      if (!isHomepage() || !viewState.homeGroups.length) { removeHomeFilterBanner(); return; }
      if (!homeFilterBanner?.isConnected) {
        homeFilterBanner = $('div', { class: 'rgh-home-filter-banner', dataset: { roomgridHomeGroupBanner: '1' } }, [
          $('span'),
          $('button', { type: 'button', onclick: () => setHomeGroupFilter([]) }, tx('清除分组筛选', 'Clear group filter', 'Gruppenfilter löschen', 'Borrar filtro de grupo', 'Limpar filtro de grupo')),
        ]);
      }
      const names = selectedHomeGroupNames();
      const allMode = viewState.homeGroupMode === 'all' && names.length > 1;
      homeFilterBanner.querySelector('span').textContent = tx(
        `启用的分组筛选：${names.join(', ') || '—'} · ${homeFilterStats.total} 张可见卡片中有 ${homeFilterStats.visible} 张匹配（${allMode ? '所有组' : '至少一个组'}）。`,
        `Active group filter: ${names.join(', ') || '—'} · ${homeFilterStats.visible} of ${homeFilterStats.total} visible cards match (${allMode ? 'all groups' : 'at least one group'}).`,
        `Aktiver Gruppenfilter: ${names.join(', ') || '—'} · ${homeFilterStats.visible} von ${homeFilterStats.total} sichtbaren Karten passen (${allMode ? 'alle Gruppen' : 'mindestens eine Gruppe'}).`,
        `Filtro de grupo activo: ${names.join(', ') || '—'} · coinciden ${homeFilterStats.visible} de ${homeFilterStats.total} tarjetas visibles (${allMode ? 'todos los grupos' : 'al menos un grupo'}).`,
        `Filtro de grupo ativo: ${names.join(', ') || '—'} · ${homeFilterStats.visible} de ${homeFilterStats.total} cartões visíveis correspondem (${allMode ? 'todos os grupos' : 'pelo menos um grupo'}).`,
      );
      const anchor = document.querySelector('#roomlist_root,[data-testid="room-list"],.RoomCardGrid') || nativeRoomCards()[0];
      if (anchor?.parentElement && homeFilterBanner.parentElement !== anchor.parentElement) anchor.parentElement.insertBefore(homeFilterBanner, anchor);
      else if (anchor?.parentElement && homeFilterBanner.nextElementSibling !== anchor) anchor.parentElement.insertBefore(homeFilterBanner, anchor);
    }

    function applyHomeGroupFilter() {
      if (!activeStore) return;
      const valid = new Set(customHomeGroups().map(group => group.id));
      const clean = viewState.homeGroups.filter(id => valid.has(id));
      if (clean.length !== viewState.homeGroups.length) { viewState.homeGroups = clean; savePrefs(); }
      const cards = nativeRoomCards();
      if (!isHomepage() || !clean.length) {
        document.querySelectorAll('.rgh-home-group-hidden').forEach(card => card.classList.remove('rgh-home-group-hidden'));
        document.body?.classList?.remove('rgh-home-group-filter-active');
        homeFilterStats = { visible: cards.filter(card => !!nativeCardId(card)).length, total: cards.filter(card => !!nativeCardId(card)).length };
        removeHomeFilterBanner();
        syncHeaderButtons();
        updateHomeFilterStatus();
        return;
      }
      const rooms = new Map((activeStore.state.rooms || []).map(room => [normalizeUsername(room.id), room]));
      let visible = 0;
      let total = 0;
      cards.forEach(card => {
        const id = nativeCardId(card);
        if (!id) { card.classList.remove('rgh-home-group-hidden'); return; }
        total += 1;
        const room = rooms.get(id);
        const matches = !!room && (viewState.homeGroupMode === 'all' ? clean.every(groupId => roomInGroup(room, groupId)) : clean.some(groupId => roomInGroup(room, groupId)));
        card.classList.toggle('rgh-home-group-hidden', !matches);
        if (matches) visible += 1;
      });
      homeFilterStats = { visible, total };
      document.body?.classList?.add('rgh-home-group-filter-active');
      updateHomeFilterBanner();
      syncHeaderButtons();
      updateHomeFilterStatus();
    }

    const scheduleHomeGroupFilter = debounce(applyHomeGroupFilter, 90);

    function setHomeGroupFilter(groupIds, mode = viewState.homeGroupMode) {
      const valid = new Set(customHomeGroups().map(group => group.id));
      viewState.homeGroups = [...new Set((groupIds || []).map(String).filter(id => valid.has(id)))].slice(0, 40);
      viewState.homeGroupMode = mode === 'all' ? 'all' : 'any';
      savePrefs();
      applyHomeGroupFilter();
      renderHeaderGroupMenu();
    }

    function positionHeaderGroupMenu() {
      if (!groupMenuPanel?.isConnected || !groupMenuButton?.isConnected) return;
      const rect = groupMenuButton.getBoundingClientRect();
      const width = Math.min(390, Math.max(260, innerWidth - 16));
      const left = Math.max(8, Math.min(rect.left, innerWidth - width - 8));
      const below = rect.bottom + 1;
      const availableBelow = innerHeight - below - 8;
      groupMenuPanel.style.width = `${width}px`;
      groupMenuPanel.style.left = `${Math.round(left)}px`;
      groupMenuPanel.style.top = `${Math.round(availableBelow >= 240 ? below : Math.max(8, rect.top - Math.min(620, groupMenuPanel.scrollHeight) - 1))}px`;
      groupMenuPanel.style.maxHeight = `${Math.max(180, Math.floor(availableBelow >= 240 ? availableBelow : rect.top - 9))}px`;
    }

    function closeHeaderGroupMenu() {
      const restoreFocus = !!groupMenuPanel?.contains(document.activeElement);
      const returnTarget = groupMenuReturnFocus?.isConnected ? groupMenuReturnFocus : groupMenuButton;
      groupMenuPanel?.remove();
      groupMenuPanel = null;
      if (groupMenuOutsideHandler) document.removeEventListener('pointerdown', groupMenuOutsideHandler, true);
      groupMenuOutsideHandler = null;
      groupMenuReturnFocus = null;
      syncHeaderButtons();
      if (restoreFocus) requestAnimationFrame(() => returnTarget?.focus?.());
    }

    function renderHeaderGroupMenu() {
      if (!groupMenuPanel?.isConnected) return;
      const groups = customHomeGroups();
      const selected = new Set(viewState.homeGroups);
      const roomCounts = new Map(groups.map(group => [group.id, (activeStore?.state?.rooms || []).filter(room => roomInGroup(room, group.id)).length]));
      groupMenuPanel.replaceChildren(...[
        $('div', { class: 'rgh-group-popover-head' }, [
          $('strong', {}, tx('按群组筛选主页', 'Filter homepage by groups', 'Startseite nach Gruppen filtern', 'Filtrar la página de inicio por grupos', 'Filtrar a página inicial por grupos')),
          $('button', { type: 'button', onclick: closeHeaderGroupMenu, title: tx('关闭', 'Close', 'Schließen'), ariaLabel: tx('关闭群组菜单', 'Close group menu', 'Gruppenmenü schließen', 'Cerrar menú de grupos', 'Fechar menu de grupos') }, '×'),
        ]),
        $('p', { class: 'rgh-group-popover-copy' }, tx('选择一个或多个自己的群组。其他模特卡片会立即从 Chaturbate 主页隐藏。', 'Choose one or more of your own groups. Other model cards are immediately hidden on the Chaturbate homepage.', 'Wähle eine oder mehrere eigene Gruppen. Andere Modelkarten werden auf der Chaturbate-Startseite sofort ausgeblendet.', 'Elige uno o más grupos propios. Las demás tarjetas de modelos se ocultarán inmediatamente en la página de inicio de Chaturbate.', 'Escolha um ou mais grupos próprios. Os outros cartões de modelos serão ocultados imediatamente na página inicial do Chaturbate.')),
        $('div', { class: 'rgh-group-popover-actions' }, [
          $('button', { class: selected.size ? '' : 'is-active', type: 'button', onclick: () => setHomeGroupFilter([]) }, tx('显示全部', 'Show all', 'Alle anzeigen', 'Mostrar todo', 'Mostrar tudo')),
        ]),
        groups.length ? $('div', { class: 'rgh-group-list' }, groups.map(group => $('label', { class: selected.has(group.id) ? 'is-active' : '' }, [
          $('input', { type: 'checkbox', checked: selected.has(group.id), onchange: event => {
            const next = new Set(viewState.homeGroups);
            if (event.target.checked) next.add(group.id); else next.delete(group.id);
            setHomeGroupFilter([...next]);
          } }),
          $('span', { title: rawUiText(groupLabel(group)) }, rawUiText(groupLabel(group))),
          $('b', { title: tx('此群组中的模特', 'Models in this group', 'Models in dieser Gruppe', 'Modelos de este grupo', 'Modelos neste grupo') }, String(roomCounts.get(group.id) || 0)),
        ]))) : $('div', { class: 'rgh-group-popover-empty' }, tx('还没有自己的群组。请在模特库中创建群组并分配模特。', 'There is no custom group yet. Create one in the model library and assign models there.', 'Noch keine eigene Gruppe vorhanden. Erstelle sie in der Modellbibliothek und ordne dort Models zu.', 'Todavía no hay ningún grupo propio. Créalo en la biblioteca de modelos y asigna modelos allí.', 'Ainda não há nenhum grupo próprio. Crie um na biblioteca de modelos e atribua modelos a ele.')),
        selected.size > 1 ? $('div', { class: 'rgh-group-mode' }, [
          $('button', { class: viewState.homeGroupMode === 'any' ? 'is-active' : '', type: 'button', onclick: () => setHomeGroupFilter(viewState.homeGroups, 'any') }, tx('任意组', 'In any group', 'In einer Gruppe', 'En cualquier grupo', 'Em qualquer grupo')),
          $('button', { class: viewState.homeGroupMode === 'all' ? 'is-active' : '', type: 'button', onclick: () => setHomeGroupFilter(viewState.homeGroups, 'all') }, tx('所有组', 'In all groups', 'In allen Gruppen', 'En todos los grupos', 'Em todos os grupos')),
        ]) : null,
        $('div', { class: 'rgh-group-popover-status' }),
        $('div', { class: 'rgh-group-popover-footer' }, [
          $('button', { type: 'button', onclick: () => { closeHeaderGroupMenu(); open('library'); } }, groups.length
            ? tx('管理群组', 'Manage groups', 'Gruppen verwalten', 'Administrar grupos', 'Gerenciar grupos')
            : tx('创建群组', 'Create group', 'Gruppe erstellen', 'Crear grupo', 'Criar grupo')),
        ]),
      ].filter(Boolean));
      updateHomeFilterStatus();
      positionHeaderGroupMenu();
    }

    function openHeaderGroupMenu(button = groupMenuButton) {
      closeGlobalMenu(false);
      if (lightweight || !activeStore) {
        location.href = new URL('/?roomgrid_groups=1', location.origin).toString();
        return;
      }
      if (groupMenuPanel?.isConnected && groupMenuButton === button) { closeHeaderGroupMenu(); return; }
      closeHeaderGroupMenu();
      groupMenuButton = button;
      groupMenuReturnFocus = document.activeElement;
      groupMenuPanel = $('section', { class: 'rgh-group-popover', dataset: { roomgridHeaderGroupMenu: '1' }, role: 'dialog', ariaLabel: tx('主页自定义群组', 'Custom groups for the homepage', 'Eigene Gruppen für die Startseite', 'Grupos propios para la página de inicio', 'Grupos próprios para a página inicial'), lang: LANG, tabIndex: '-1' });
      document.body.appendChild(groupMenuPanel);
      renderHeaderGroupMenu();
      groupMenuOutsideHandler = event => {
        if (!groupMenuPanel?.contains(event.target) && !groupMenuButton?.contains(event.target)) closeHeaderGroupMenu();
      };
      setTimeout(() => groupMenuOutsideHandler && document.addEventListener('pointerdown', groupMenuOutsideHandler, true), 0);
      syncHeaderButtons();
      requestAnimationFrame(() => groupMenuPanel?.querySelector('button,input')?.focus());
    }

    function closeGlobalMenu(restoreFocus = true) {
      if (globalMenuOutsideHandler) document.removeEventListener('pointerdown', globalMenuOutsideHandler, true);
      globalMenuOutsideHandler = null;
      globalMenuPanel?.remove();
      globalMenuPanel = null;
      const returnTarget = globalMenuReturnFocus;
      globalMenuReturnFocus = null;
      syncHeaderButtons();
      if (restoreFocus && returnTarget?.isConnected) requestAnimationFrame(() => returnTarget.focus?.());
    }

    function positionGlobalMenu() {
      if (!globalMenuPanel?.isConnected) return;
      const rect = globalMenuButton?.getBoundingClientRect?.();
      const width = Math.min(520, Math.max(300, window.innerWidth - 16));
      let left = rect ? rect.left : window.innerWidth - width - 18;
      let top = rect ? rect.bottom : 64;
      left = Math.max(8, Math.min(window.innerWidth - width - 8, left));
      top = Math.max(8, Math.min(window.innerHeight - 120, top));
      Object.assign(globalMenuPanel.style, { left: `${Math.round(left)}px`, top: `${Math.round(top)}px`, maxHeight: `${Math.max(110, Math.round(window.innerHeight - top - 8))}px` });
    }

    function suiteUrl(view) {
      const url = new URL('/', location.origin);
      if (view === 'workstation') url.searchParams.set('multicam_mode', '1');
      else { url.searchParams.set('multicam_discover', '1'); url.searchParams.set('suite_view', view); }
      return url.toString();
    }

    function menuItem(spec) {
      return $('button', {
        class: `rgh-global-item${spec.active ? ' is-active' : ''}`,
        type: 'button', dataset: { roomgridGlobalTarget: spec.id },
        onclick: () => { closeGlobalMenu(false); spec.run(); },
      }, [$('b', {}, spec.icon), $('span', {}, [$('span', {}, spec.label), $('small', {}, spec.detail || '')])]);
    }

    function openGlobalMenu(button = null) {
      if (globalMenuPanel?.isConnected && (!button || globalMenuButton === button)) { closeGlobalMenu(); return; }
      closeGlobalMenu(false);
      closeHeaderGroupMenu();
      globalMenuButton = button || document.querySelector('.rgh-header-brand');
      globalMenuReturnFocus = document.activeElement;
      const goHub = view => {
        location.href = suiteUrl(view);
      };
      const goControl = tab => {
        if (!lightweight && activeStore && activeAnalytics) { close(); openControlCenter(activeStore, activeAnalytics, activeNotifications, activeWindows, tab); }
        else location.href = new URL(`/?roomgrid_control=${encodeURIComponent(tab)}`, location.origin).toString();
      };
      const groups = [
        [tx('主要视图', 'Main views', 'Hauptansichten'), [
          { id: 'workstation', icon: '▦', label: tx('多画面工作站', 'MultiCam workstation', 'MultiCam-Arbeitsbereich'), detail: tx('摄像头网格、音频和布局', 'Camera grid, audio and layouts', 'Kameraraster, Audio und Layouts'), run: () => openNoopener(suiteUrl('workstation')) },
          { id: 'discover', icon: '⌁', label: tx('发现', 'Discover', 'Entdecken'), detail: tx('完整目录、过滤器和排序', 'Full catalog, filters and sorting', 'Vollständiger Katalog, Filter und Sortierung'), run: () => openNoopener(suiteUrl('discover')) },
          { id: 'dashboard', icon: '⌂', label: tx('个人首页', 'Personal dashboard', 'Persönliche Startseite'), detail: tx('收藏、动态和快捷入口', 'Favorites, activity and shortcuts', 'Favoriten, Aktivität und Schnellzugriffe'), run: () => openNoopener(suiteUrl('dashboard')) },
          { id: 'tags', icon: '#', label: tx('标签浏览器', 'Tag explorer', 'Tag-Explorer'), detail: tx('组合、趋势和相关标签', 'Combinations, trends and related tags', 'Kombinationen, Trends und verwandte Tags'), run: () => openNoopener(suiteUrl('tags')) },
        ]],
        [tx('资料和统计', 'Library and statistics', 'Bibliothek und Statistik'), [
          { id: 'stats', icon: '▥', label: tx('统计中心', 'Statistics Center', 'Statistikzentrum'), detail: tx('模型比较和本地统计', 'Model comparison and local statistics', 'Modelvergleich und lokale Statistik'), active: !!root && viewState.view === 'stats', run: () => goHub('stats') },
          { id: 'library', icon: '★', label: tx('模型库', 'Model library', 'Modellbibliothek'), detail: tx('资料、标签、群组和备注', 'Profiles, tags, groups and notes', 'Profile, Tags, Gruppen und Notizen'), active: !!root && viewState.view === 'library', run: () => goHub('library') },
          { id: 'following', icon: '♥', label: (I18N[LANG]?.followingUi || I18N.en.followingUi).nav, detail: (I18N[LANG]?.followingUi || I18N.en.followingUi).description, active: !!root && viewState.view === 'following', run: () => goHub('following') },
          { id: 'user', icon: '◎', label: tx('我的用户', 'My user', 'Mein Nutzer'), detail: tx('偏好、使用情况和账户数据', 'Preferences, usage and account data', 'Vorlieben, Nutzung und Kontodaten'), active: !!root && viewState.view === 'user', run: () => goHub('user') },
          { id: 'analytics', icon: '▤', label: tx('分析工作室', 'Analytics Studio', 'Analytics Studio'), detail: tx('时间范围、热图和导出', 'Ranges, heatmaps and exports', 'Zeiträume, Heatmaps und Exporte'), run: () => goControl('analytics') },
        ]],
        [tx('设置和维护', 'Settings and maintenance', 'Einstellungen und Wartung'), [
          { id: 'homepage', icon: '⌂', label: tx('自定义首页', 'Customize homepage', 'Startseite anpassen'), detail: tx('卡片、过滤器和可见信息', 'Cards, filters and visible details', 'Karten, Filter und sichtbare Informationen'), run: () => goControl('homepage') },
          { id: 'appearance', icon: '◐', label: tx('设计', 'Appearance', 'Design'), detail: tx('颜色、密度和表面', 'Colors, density and surfaces', 'Farben, Dichte und Oberflächen'), run: () => goControl('appearance') },
          { id: 'workspaces', icon: '◫', label: tx('工作区和群组', 'Workspaces and groups', 'Arbeitsbereiche und Gruppen'), detail: tx('布局、模板和分配', 'Layouts, templates and assignments', 'Layouts, Vorlagen und Zuordnungen'), run: () => goControl('workspaces') },
          { id: 'data', icon: '⇅', label: tx('数据和备份', 'Data and backup', 'Daten und Sicherung'), detail: tx('导入、导出和恢复', 'Import, export and recovery', 'Import, Export und Wiederherstellung'), run: () => goControl('data') },
          { id: 'performance', icon: '⚙', label: tx('窗口和性能', 'Windows and performance', 'Fenster und Leistung'), detail: tx('资源配置和预览限制', 'Resource profiles and preview limits', 'Ressourcenprofile und Vorschaulimits'), run: () => goControl('performance') },
          { id: 'privacy', icon: '◇', label: tx('隐私', 'Privacy', 'Datenschutz'), detail: tx('历史、私人会话和本地数据', 'History, private session and local data', 'Verlauf, private Sitzung und lokale Daten'), run: () => goControl('privacy') },
          { id: 'diagnostics', icon: '＋', label: tx('诊断', 'Diagnostics', 'Diagnose'), detail: tx('自检、路由和恢复', 'Self-check, routes and recovery', 'Selbsttest, Routen und Wiederherstellung'), run: () => goControl('diagnostics') },
        ]],
      ];
      globalMenuPanel = $('section', { class: 'rgh-global-menu', dataset: { roomgridGlobalMenu: '1' }, role: 'dialog', ariaLabel: tx('RoomGrid 主菜单', 'RoomGrid main menu', 'RoomGrid-Hauptmenü'), lang: LANG, tabIndex: '-1' }, [
        $('div', { class: 'rgh-global-head' }, [
          $('div', {}, [$('strong', {}, [$('span', { dataset: { roomgridBrandName: '1' } }, roomGridBrandIdentity(activeStore?.state?.settings).name), ' ', $('span', { dataset: { roomgridBrandVersion: '1' } }, `v${META.version}`)]), $('small', {}, tx('所有页面、设置和工具位于一个位置', 'All pages, settings and tools in one place', 'Alle Seiten, Einstellungen und Werkzeuge an einem Ort'))]),
          $('button', { type: 'button', ariaLabel: tx('关闭', 'Close', 'Schließen'), onclick: () => closeGlobalMenu() }, '×'),
        ]),
        ...groups.map(([title, items]) => $('section', { class: 'rgh-global-section' }, [$('h3', {}, title), $('div', { class: 'rgh-global-grid' }, items.map(menuItem))])),
        $('div', { class: 'rgh-global-foot' }, tx('菜单会保持在可见窗口内；所有 RoomGrid 数据仍保存在本地。', 'The menu stays inside the visible window; all RoomGrid data remains local.', 'Das Menü bleibt im sichtbaren Fenster; alle RoomGrid-Daten bleiben lokal.')),
      ]);
      document.body.appendChild(globalMenuPanel);
      positionGlobalMenu();
      globalMenuOutsideHandler = event => { if (!globalMenuPanel?.contains(event.target) && !globalMenuButton?.contains?.(event.target)) closeGlobalMenu(); };
      setTimeout(() => globalMenuOutsideHandler && document.addEventListener('pointerdown', globalMenuOutsideHandler, true), 0);
      syncHeaderButtons();
      requestAnimationFrame(() => globalMenuPanel?.querySelector('.rgh-global-item')?.focus());
    }

    function createHeaderMenu() {
      const menu = $('div', { class: 'rgh-header-menu', dataset: { roomgridHeaderMenu: '1' }, role: 'navigation', ariaLabel: tx('RoomGrid 页面', 'RoomGrid pages', 'RoomGrid-Seiten'), lang: LANG });
      const specs = [
        ['stats', '▥', tx('统计', 'Statistics', 'Statistiken')],
        ['library', '★', tx('模型库', 'Model library', 'Model-Bibliothek')],
        ['following', '♥', (I18N[LANG]?.followingUi || I18N.en.followingUi).nav],
        ['user', '◎', tx('我的用户', 'My user', 'Mein Nutzer')],
      ];
      const go = view => {
        location.href = suiteUrl(view);
      };
      const identity = roomGridBrandIdentity(activeStore?.state?.settings);
      menu.appendChild($('button', { class: 'rgh-header-brand', type: 'button', dataset: { roomgridGlobalMenuButton: '1' }, onclick: event => openGlobalMenu(event.currentTarget), title: `${tx('RoomGrid 主菜单', 'RoomGrid main menu', 'RoomGrid-Hauptmenü')} · v${META.version}` }, [roomGridBrandMark(activeStore?.state?.settings, { size: 22 }), ' ', $('b', { dataset: { roomgridBrandVersion: '1' } }, identity.showVersion ? `v${META.version}` : '')]));
      specs.forEach(([id, icon, label]) => menu.appendChild($('button', { type: 'button', dataset: { roomgridHeaderView: id }, onclick: () => go(id), title: label }, [$('b', {}, icon), $('span', {}, label)])));
      menu.appendChild($('button', { type: 'button', dataset: { roomgridHeaderHomepage: '1' }, onclick: () => {
        if (!lightweight && activeStore && activeAnalytics) openControlCenter(activeStore, activeAnalytics, activeNotifications, activeWindows, 'homepage');
        else location.href = new URL('/?roomgrid_home_options=1', location.origin).toString();
      }, title: tx('自定义原始首页', 'Customize original homepage', 'Originale Startseite anpassen') }, [$('b', {}, '▦'), $('span', {}, tx('首页', 'Homepage', 'Startseite'))]));
      groupMenuButton = $('button', { type: 'button', dataset: { roomgridHeaderGroups: '1' }, onclick: event => openHeaderGroupMenu(event.currentTarget), title: tx('按自己的群组筛选主页', 'Filter homepage by your own groups', 'Startseite nach eigenen Gruppen filtern', 'Filtrar la página de inicio por tus propios grupos', 'Filtrar a página inicial por seus próprios grupos') }, [$('span', {}, tx('群组', 'Groups', 'Gruppen', 'Grupos', 'Grupos')), $('b', { class: 'rgh-header-group-count' })]);
      menu.appendChild(groupMenuButton);
      menu.appendChild(createLanguageSwitcher('rgh-language-select'));
      return menu;
    }

    function ensureHeaderMenu() {
      if (headerMenu?.isConnected) return;
      const target = findHeaderHost();
      if (!target) return;
      closeHeaderGroupMenu();
      headerHost?.removeAttribute?.('data-roomgrid-header-host');
      headerHost = target.closest('header,[role="banner"],#header,nav') || target;
      headerHost.dataset.roomgridHeaderHost = '1';
      headerMenu = createHeaderMenu();
      target.appendChild(headerMenu);
      syncHeaderButtons();
      syncTop();
    }

    function syncHeaderButtons() {
      document.querySelectorAll('[data-roomgrid-global-menu-button]').forEach(button => button.classList.toggle('is-active', !!globalMenuPanel?.isConnected && button === globalMenuButton));
      document.querySelectorAll('[data-roomgrid-header-view]').forEach(button => button.classList.toggle('is-active', !!root && button.dataset.roomgridHeaderView === viewState.view));
      document.querySelectorAll('[data-roomgrid-header-groups]').forEach(button => {
        button.classList.toggle('is-active', !!groupMenuPanel?.isConnected && button === groupMenuButton);
        button.classList.toggle('has-filter', viewState.homeGroups.length > 0);
        const count = button.querySelector('.rgh-header-group-count');
        if (count) { count.textContent = String(viewState.homeGroups.length); count.hidden = viewState.homeGroups.length === 0; }
      });
    }

    function syncTop() {
      if (!root) return;
      const rect = headerHost?.getBoundingClientRect?.();
      const top = rect && rect.bottom > 0 && rect.top < 160 ? Math.min(180, Math.max(0, Math.round(rect.bottom))) : 0;
      root.style.setProperty('--rgh-top', `${top}px`);
    }

    function syncPrivateCacheState() {
      const next = activeAnalytics?.isPrivateSession?.() === true;
      if (next !== cachedPrivateSession) {
        cachedPrivateSession = next;
        followingCacheChecked = '';
        if (next && followingState.cached) followingState = { status: 'idle', rows: [], pages: 0, partial: false, error: '', recognized: false };
        mediaCacheGeneration += 1;
        modelCoverCache.clear();
        hubPageCache.clear();
      }
    }

    function invalidate(_state, path) {
      syncPrivateCacheState();
      // Layout, appearance and filter preferences do not change historical
      // model/event data. Store supplies a precise settings path for these.
      if (typeof path === 'string' && (path === 'settings' || path.startsWith('settings:'))) {
        if (cache) cache.storeRevision = activeStore.revision;
        if (root) scheduleRender();
        return;
      }
      cacheGeneration += 1;
      cacheDirty = true;
      // Keep an already usable snapshot on screen. Discarding both the cache
      // and an in-flight promise here used to start another 30k+ model index
      // build on every embedded page switch or store update. The running build
      // now finishes exactly once; a newer generation is refreshed quietly.
      if (cache) scheduleCacheRefresh();
      if (root) scheduleRender();
    }

    function invalidateQuietly() {
      syncPrivateCacheState();
      cacheGeneration += 1;
      cacheDirty = true;
      // Summaries are keyed by their immutable index object. A dirty index is
      // still a valid last-known snapshot; a replacement gets a new memo key.
      if (cache) scheduleCacheRefresh();
    }

    // Building the combined library/statistics index can touch tens of
    // thousands of models and up to 100k events. Yield regularly so the
    // native header, close button and page links stay responsive while the
    // richer views finish preparing in the background.
    const yieldToUi = () => globalThis.scheduler?.yield
      ? globalThis.scheduler.yield()
      : new Promise(resolve => setTimeout(resolve, 0));
    async function forEachProgressively(list, visit, budgetMs = 10) {
      let sliceStartedAt = performance.now();
      for (let index = 0; index < list.length; index += 1) {
        visit(list[index], index);
        if (index && index % 16 === 0 && performance.now() - sliceStartedAt >= budgetMs) {
          await yieldToUi();
          sliceStartedAt = performance.now();
        }
      }
    }

    async function filterHubItems(items, predicate, revision) {
      const filtered = [];
      let sliceStartedAt = performance.now();
      for (let index = 0; index < items.length; index += 1) {
        if (revision !== renderRevision || !root?.isConnected) return null;
        if (predicate(items[index])) filtered.push(items[index]);
        if (index && index % 128 === 0 && performance.now() - sliceStartedAt >= 8) {
          await yieldToUi();
          if (revision !== renderRevision || !root?.isConnected) return null;
          sliceStartedAt = performance.now();
        }
      }
      return filtered;
    }

    async function sortHubItemsProgressively(items, compare, revision) {
      // A background index is not tied to a visible render. It must finish
      // once even when the user switches pages; publication is guarded by
      // loadData's generation tracking. Visible sorts still cancel promptly.
      const cancelled = () => revision != null && (revision !== renderRevision || !root?.isConnected);
      if (items.length < 2048) return items.sort(compare);
      // Index and filtered views often contain a few already sorted runs.
      // Merge those directly; a highly disordered list uses the normal sort.
      const boundaries = [0];
      let checkStartedAt = performance.now();
      for (let index = 1; index < items.length; index += 1) {
        if (compare(items[index - 1], items[index]) > 0) {
          boundaries.push(index);
          if (boundaries.length > 64) break;
        }
        if ((index & 255) === 0 && performance.now() - checkStartedAt >= 8) {
          await yieldToUi();
          if (cancelled()) return null;
          checkStartedAt = performance.now();
        }
      }
      if (cancelled()) return null;
      if (boundaries.length === 1) return items;
      let source = items.slice();
      let target = new Array(source.length);
      let operations = 0;
      let sliceStartedAt = performance.now();
      if (boundaries.length <= 64) {
        boundaries.push(source.length);
        let runs = boundaries;
        while (runs.length > 2) {
          const nextRuns = [0];
          for (let run = 0; run < runs.length - 1; run += 2) {
            const start = runs[run], middle = runs[run + 1], end = runs[Math.min(run + 2, runs.length - 1)];
            let left = start, right = middle, output = start;
            while (left < middle || right < end) {
              if (right >= end || (left < middle && compare(source[left], source[right]) <= 0)) target[output++] = source[left++];
              else target[output++] = source[right++];
              operations += 1;
              if ((operations & 255) === 0 && performance.now() - sliceStartedAt >= 8) {
                await yieldToUi();
                if (cancelled()) return null;
                sliceStartedAt = performance.now();
              }
            }
            nextRuns.push(end);
          }
          [source, target] = [target, source];
          runs = nextRuns;
          if (cancelled()) return null;
        }
        return source;
      }
      for (let width = 1; width < source.length; width *= 2) {
        for (let start = 0; start < source.length; start += width * 2) {
          const middle = Math.min(start + width, source.length);
          const end = Math.min(start + width * 2, source.length);
          let left = start;
          let right = middle;
          let output = start;
          while (left < middle && right < end) {
            if (compare(source[left], source[right]) <= 0) target[output++] = source[left++];
            else target[output++] = source[right++];
            operations += 1;
            if ((operations & 255) === 0 && performance.now() - sliceStartedAt >= 8) {
              await yieldToUi();
              if (cancelled()) return null;
              sliceStartedAt = performance.now();
            }
          }
          while (left < middle) target[output++] = source[left++];
          while (right < end) target[output++] = source[right++];
        }
        [source, target] = [target, source];
        if (cancelled()) return null;
      }
      return source;
    }

    async function buildDataIndex(options = {}) {
        // The shell opens immediately, but every rich data view must consume
        // the same fully hydrated analytics snapshot. Without this barrier,
        // rapid navigation could cache a partial model list while IndexedDB
        // was still streaming in the remaining account history.
        // The first paint deliberately skips that barrier. Analytics hydrates
        // incrementally, so the synchronous maps already contain a useful
        // partial snapshot. Waiting for all old events before painting made
        // Stats/Library/User look frozen for large local histories. The full
        // refresh still uses the barrier in the idle background path.
        if (options.waitForReady !== false) await activeAnalytics.whenReady?.();
        const historyReady = activeAnalytics.isReady?.() !== false;
        const analyticsRevision = activeAnalytics.getDataRevision?.();
        const storeRevision = activeStore.revision;
        const [models, events, quality, accountSnapshots] = await Promise.all([
          Promise.resolve(activeAnalytics.getModelsSync()),
          Promise.resolve(activeAnalytics.getEventsSync({ limit: 100000 })),
          Promise.resolve(activeAnalytics.getQualitySamplesSync({ limit: 20000 })),
          Promise.resolve(activeAnalytics.getAccountSnapshotsSync({ limit: 20000 })),
        ]);
        const rooms = (activeStore.state.rooms || []).slice();
        const modelMap = new Map(models.map(model => [model.id, model]));
        const roomMap = new Map(rooms.map(room => [room.id, room]));
        const eventMap = new Map();
        const qualityMap = new Map();
        await forEachProgressively(events, event => {
          if (!event.id) return;
          if (!eventMap.has(event.id)) eventMap.set(event.id, []);
          eventMap.get(event.id).push(event);
        });
        await forEachProgressively(quality, sample => {
          if (!sample.id) return;
          if (!qualityMap.has(sample.id)) qualityMap.set(sample.id, []);
          qualityMap.get(sample.id).push(sample);
        });
        const ids = new Set([...modelMap.keys(), ...roomMap.keys(), ...eventMap.keys()]);
        const totalWatchMs = [...ids].reduce((sum, id) => sum + Math.max(0, Number(modelMap.get(id)?.totalMs) || 0), 0);
        let items = [];
        const indexBuiltAt = Date.now();
        await forEachProgressively([...ids], id => {
          if (!isLikelyUsername(id)) return;
          const model = modelMap.get(id) || { id, totalMs: 0, sessions: 0, hours: [], days: {}, tags: [] };
          const room = roomMap.get(id) || null;
          const profile = activeAnalytics.getProfileSync(id) || null;
          const modelEvents = eventMap.get(id) || [];
          const samples = qualityMap.get(id) || [];
          const counts = {};
          let lastEventAt = 0;
          for (const event of modelEvents) {
            counts[event.type] = (counts[event.type] || 0) + 1;
            lastEventAt = Math.max(lastEventAt, Number(event.at) || 0);
          }
          let startupTotal = 0; let stalls = 0; let dropped = 0; let frames = 0;
          for (const sample of samples) {
            startupTotal += Number(sample.startupMs) || 0;
            stalls += Number(sample.stalls) || 0;
            dropped += Number(sample.droppedFrames) || 0;
            frames += Number(sample.totalFrames) || 0;
          }
          const avgStartup = samples.length ? startupTotal / samples.length : 0;
          let peakIndex = 0; let peakValue = 0;
          const observedHours = Array.isArray(model.hours) ? model.hours : [];
          const observedHourCount = Math.min(168, observedHours.length);
          for (let index = 0; index < observedHourCount; index += 1) {
            const value = Math.max(0, Number(observedHours[index]) || 0);
            if (value > peakValue) { peakValue = value; peakIndex = index; }
          }
          const tags = [...new Set([...(room?.localTags || []), ...(model.tags || []), ...(profile?.tags || [])])].slice(0, 80);
          const status = freshObservedStatus(room, model, profile, indexBuiltAt);
          const searchText = `${id} ${profile?.displayName || ''} ${profile?.bio || ''} ${tags.join(' ')} ${room?.notes || ''}`.toLocaleLowerCase();
          items.push({
            id, model, room, profile, events: modelEvents, counts, samples, tags, status,
            searchText,
            totalMs: Math.max(0, Number(model.totalMs) || 0), sessions: Math.max(0, Number(model.sessions) || 0),
            activeDays: Object.values(model.days || {}).filter(value => Number(value) > 0).length,
            avgSessionMs: model.sessions ? model.totalMs / model.sessions : 0,
            share: totalWatchMs ? model.totalMs / totalWatchMs : 0,
            avgStartup, stalls, dropRate: frames ? dropped / frames : 0, peakIndex,
            lastActivity: Math.max(Number(model.lastObservedAt) || 0, Number(model.lastWatchedAt) || 0, Number(model.lastOnlineAt) || 0, Number(room?.lastSeenOnline) || 0, lastEventAt),
          });
        }, 10);
        await yieldToUi();
        items = await sortHubItemsProgressively(items, (a, b) => b.totalMs - a.totalMs || b.lastActivity - a.lastActivity || a.id.localeCompare(b.id), null);
        items.forEach((item, index) => { item.rank = index + 1; });
        const recentCutoff = Date.now() - 30 * 86400000;
        const summary = {
          watched: items.filter(item => item.totalMs > 0),
          sessions: items.reduce((sum, item) => sum + item.sessions, 0),
          previews: events.reduce((sum, event) => sum + (event.type === 'preview' ? 1 : 0), 0),
          recentEvents: events.reduce((sum, event) => sum + (Number(event.at) >= recentCutoff ? 1 : 0), 0),
        };
        summary.top = summary.watched[0] || null;
      return { models, events, quality, accountSnapshots, rooms, items, totalWatchMs, summary, usage: activeAnalytics.getUsageSummary(), analyticsRevision, storeRevision, historyReady };
    }

    // Discover keeps the complete public catalog in its own IndexedDB cache.
    // Recover it into the stable analytics store after an update so the native
    // library does not suddenly shrink to only the models watched locally.
    async function restorePersistedCatalog() {
      if (catalogRestorePromise || !activeAnalytics || typeof activeAnalytics.observeModelsBatch !== 'function') return catalogRestorePromise;
      const bridge = globalThis.RoomGridCatalogBridge;
      if (!bridge?.loadFullModels) return null;
      catalogRestorePromise = (async () => {
        catalogRestoreStatus = 'pending';
        try {
          await activeAnalytics.whenReady?.();
          const snapshot = await bridge.loadFullModels();
          const rooms = Array.isArray(snapshot?.rooms) ? snapshot.rooms : [];
          if (!rooms.length) { catalogRestoreStatus = 'empty'; return 0; }
          const observedAt = Math.max(0, Number(snapshot.fetchedAt || snapshot.savedAt) || Date.now());
          const payload = rooms.map(room => ({
            id: room.id,
            currentShow: room.currentShow,
            viewerCount: room.viewers,
            tags: room.tags || [],
            subject: room.subject || '',
            country: room.country || '',
            location: room.location || '',
            gender: room.gender || 'unknown',
            age: room.age || 0,
            followers: room.followers || 0,
            secondsOnline: room.secondsOnline || 0,
            isHd: !!room.isHd,
            isNew: !!room.isNew,
            isGaming: !!room.isGaming,
            source: 'roomgrid-catalog-cache',
            observedAt,
          }));
          const changed = await activeAnalytics.observeModelsBatch(payload);
          await activeAnalytics.flush?.();
          catalogRestoreStatus = changed > 0 ? 'done' : 'already';
          return changed;
        } catch (_) { catalogRestoreStatus = 'error'; return 0; }
        finally { catalogRestorePromise = null; }
      })();
      return catalogRestorePromise;
    }

    function schedulePersistedCatalogRestore() {
      if (catalogRestorePromise || !activeAnalytics || !globalThis.RoomGridCatalogBridge?.loadFullModels) return;
      const run = () => restorePersistedCatalog().then(changed => {
        if (changed > 0) {
          invalidateQuietly();
          if (root) scheduleRender();
        }
      }).catch(() => {});
      if ('requestIdleCallback' in window) requestIdleCallback(run, { timeout: 5000 });
      else setTimeout(run, 1200);
    }

    async function loadData(options = {}) {
      // A cached snapshot remains useful while a newer, complete snapshot is
      // built. Never make a page switch wait for that background refresh.
      if (cache) {
        if (cache.analyticsRevision !== activeAnalytics.getDataRevision?.() || cache.storeRevision !== activeStore.revision) {
          cacheDirty = true; scheduleCacheRefresh();
        }
        if (cacheDirty) scheduleCacheRefresh();
        return cache;
      }
      if (cachePromise) return cachePromise;
      const generation = cacheGeneration;
      const allowPartial = options.allowPartial === true;
      const pending = buildDataIndex({ waitForReady: !allowPartial }).then(value => {
        cache = value;
        // Partial data is intentionally marked dirty so the idle refresh can
        // replace it with the fully hydrated index once IndexedDB is ready.
        cacheDirty = (allowPartial && !value.historyReady) || generation !== cacheGeneration;
        if (cachePromise === pending) cachePromise = null;
        if (cacheDirty) scheduleCacheRefresh();
        // Keep the first paint fast; recovery runs in an idle slice and then
        // refreshes the visible count/cards without navigating away.
        schedulePersistedCatalogRestore();
        return cache;
      }).catch(error => {
        if (cachePromise === pending) cachePromise = null;
        throw error;
      });
      cachePromise = pending;
      return cachePromise;
    }

    function requestIdleWork(run, timeout = 2500) {
      if ('requestIdleCallback' in window) return requestIdleCallback(run, { timeout });
      return setTimeout(() => run({ didTimeout: true, timeRemaining: () => 0 }), Math.min(timeout, 500));
    }

    function cancelIdleWork(handle) {
      if (!handle) return;
      if ('cancelIdleCallback' in window) cancelIdleCallback(handle);
      else clearTimeout(handle);
    }

    function scheduleCacheWarmup() {
      if (cache || cachePromise || cacheWarmupHandle || !activeAnalytics) return;
      cacheWarmupHandle = requestIdleWork(() => {
        cacheWarmupHandle = 0;
        // Foreground navigation shares this promise. Never park it behind
        // complete IndexedDB hydration; the full refresh has its own promise.
        if (activeAnalytics && !cache && !cachePromise) loadData({ allowPartial: true }).catch(() => {});
      }, 3500);
    }

    function scheduleCacheRefresh() {
      if (!cacheDirty || !cache || !root?.isConnected || cacheRefreshPromise || cacheRefreshHandle || cacheRefreshTimer || !activeAnalytics) return;
      cacheRefreshTimer = setTimeout(() => {
        cacheRefreshTimer = 0;
        cacheRefreshHandle = requestIdleWork(() => {
          cacheRefreshHandle = 0;
          if (!cacheDirty || !root?.isConnected || !activeAnalytics || cacheRefreshPromise) return;
          const generation = cacheGeneration;
          cacheRefreshPromise = buildDataIndex().then(value => {
            cache = value;
            // Old handlers refer to their data snapshot. Drop completed pages
            // when replacing the index rather than retaining several histories.
            hubPageCache.clear();
            cacheDirty = generation !== cacheGeneration;
            cacheRefreshPromise = null;
            if (root) scheduleRender();
            if (cacheDirty) scheduleCacheRefresh();
          }).catch(() => { cacheRefreshPromise = null; });
        }, 5000);
      }, 1200);
    }

    function queueMediaHydration(node, task) {
      mediaHydrationQueue.push({ node, task });
      if (mediaHydrationHandle || mediaHydrationTimer) return;
      const drain = deadline => {
        mediaHydrationHandle = 0;
        let launched = 0;
        while (mediaHydrationQueue.length && launched < 4 && (deadline.didTimeout || deadline.timeRemaining() > 3)) {
          const entry = mediaHydrationQueue.shift();
          if (entry.node?.isConnected) Promise.resolve().then(entry.task).catch(() => {});
          launched += 1;
        }
        if (mediaHydrationQueue.length) mediaHydrationHandle = requestIdleWork(drain, 2200);
      };
      mediaHydrationTimer = setTimeout(() => {
        mediaHydrationTimer = 0;
        mediaHydrationHandle = requestIdleWork(drain, 2200);
      }, 500);
    }

    function spark(values, limit = 14) {
      const list = (values || []).slice(-limit);
      const max = Math.max(1, ...list.map(value => Number(value) || 0));
      return $('div', { class: 'rgh-spark', ariaLabel: tx('活动趋势', 'Activity trend', 'Aktivitätstrend') }, list.map(value => $('i', { style: { height: `${Math.max(6, Math.round((Number(value) || 0) / max * 100))}%` } })));
    }

    function bindLiveHover(media, id) {
      if (!matchMedia('(hover:hover) and (pointer:fine)').matches || activeStore.state.settings.normalHoverLivePreview === false) return;
      const delay = clampInt(activeStore.state.settings.normalHoverLivePreviewDelay, 0, 1000, 250);
      media.addEventListener('pointerenter', () => { clearTimeout(hoverTimer); hoverTimer = setTimeout(() => { if (media.matches(':hover')) RoomGridUltimate.startInlineHoverPreview(id, media); }, delay); });
      media.addEventListener('pointerleave', () => { clearTimeout(hoverTimer); RoomGridUltimate.stopInlineHoverPreview(media); });
    }

    function publicProfileExtras(item) {
      const profile = item.profile;
      const sections = (profile?.sections || []).slice(0, 8);
      const links = (profile?.links || []).filter(link => {
        try { const url = new URL(link); return ['http:', 'https:'].includes(url.protocol) && url.hostname !== location.hostname; } catch (_) { return false; }
      }).slice(0, 16);
      if (!sections.length && !links.length) return null;
      const serviceName = raw => {
        try {
          const host = new URL(raw).hostname.replace(/^www\./iu, '').toLocaleLowerCase();
          if (host === 'x.com' || host.includes('twitter.com')) return 'X / Twitter';
          if (host.includes('instagram.com')) return 'Instagram';
          if (host.includes('tiktok.com')) return 'TikTok';
          if (host.includes('youtube.com') || host === 'youtu.be') return 'YouTube';
          if (host.includes('onlyfans.com')) return 'OnlyFans';
          if (host.includes('snapchat.com')) return 'Snapchat';
          return host;
        } catch (_) { return tx('链接', 'Link', 'Link'); }
      };
      return $('details', { class: 'rgh-public-profile' }, [
        $('summary', {}, tx('公开简介和链接', 'Public profile text and links', 'Öffentliche Profiltexte und Links')),
        $('div', { class: 'rgh-public-profile-body' }, [
          ...sections.map(section => $('section', {}, [$('strong', {}, section.label), $('p', {}, section.text)])),
          links.length ? $('div', { class: 'rgh-profile-links' }, links.map(link => $('a', { href: link, target: '_blank', rel: 'noopener noreferrer', title: link }, serviceName(link)))) : null,
        ]),
      ]);
    }

    function modelMedia(item) {
      const mediaGeneration = mediaCacheGeneration;
      const saved = [...new Set((item.model.previewUrls || []).filter(Boolean))].reverse();
      const candidates = [...new Set([...saved, thumbUrl(item.id), smallThumbUrl(item.id), generatedCoverUrl(item.id)])];
      let candidateIndex = 0;
      const img = $('img', {
        src: generatedCoverUrl(item.id),
        alt: tx(`${item.id} 预览`, `${item.id} preview`, `${item.id} Vorschau`, `Vista previa de ${item.id}`, `Prévia de ${item.id}`),
        loading: 'lazy', referrerPolicy: 'no-referrer',
        onerror: event => {
          if (event.currentTarget.dataset.coverFallback === 'generated-local') return;
          candidateIndex += 1;
          if (candidates[candidateIndex]) event.currentTarget.src = candidates[candidateIndex];
          else {
            // The final candidate is always the local generated cover. Keep a
            // visible image even when all public thumbnail requests fail.
            event.currentTarget.dataset.coverFallback = 'generated-local';
            media.dataset.roomgridMediaSource = 'generated-local-cover';
            if (sourceLabel) sourceLabel.textContent = tx('Lokales Camclient-Cover', 'Local Camclient cover', 'Lokales Camclient-Cover');
            event.currentTarget.classList.remove('is-error');
            event.currentTarget.src = generatedCoverUrl(item.id);
          }
        },
      });
      const avatar = $('img', { class: 'rgh-avatar', src: generatedCoverUrl(item.id), alt: '', loading: 'lazy', referrerPolicy: 'no-referrer', onerror: event => { if (!event.currentTarget.dataset.fallback) { event.currentTarget.dataset.fallback = '1'; event.currentTarget.src = thumbUrl(item.id); } else event.currentTarget.classList.add('is-error'); } });
      const media = $('div', { class: 'rgh-media', dataset: { initial: item.id.slice(0, 1).toLocaleUpperCase(), roomgridMediaSource: saved.length ? 'saved-public-preview' : 'current-public-thumbnail' } }, [
        img, avatar,
        $('span', { class: `rgh-status ${item.status === 'online' || item.status === 'public' ? 'online' : ''}` }, statusLabel(item.status)),
        item.rank ? $('span', { class: 'rgh-rank' }, `#${item.rank}`) : null,
        $('span', { class: 'rgh-media-source' }, saved.length
          ? tx('最后已知的公开预览', 'Last known public preview', 'Letzte bekannte öffentliche Vorschau')
          : (libraryStatusBucket(item) === 'live'
            ? tx('当前公开预览', 'Current public preview', 'Aktuelle öffentliche Vorschau')
            : tx('离线时可能只有占位图', 'Offline may only provide a placeholder', 'Offline eventuell nur Platzhalter'))),
      ]);
      media.style.backgroundImage = `url("${generatedCoverUrl(item.id)}")`;
      media.style.backgroundSize = 'cover';
      bindLiveHover(media, item.id);
      const sourceLabel = media.querySelector('.rgh-media-source');
      let coverRevision = 0;
      let currentCoverKey = '';
      let publicThumbnailStarted = false;
      const usePublicThumbnail = () => {
        if (publicThumbnailStarted || currentCoverKey || !media.isConnected || mediaGeneration !== mediaCacheGeneration) return;
        publicThumbnailStarted = true;
        candidateIndex = 0;
        img.src = candidates[0];
        avatar.src = smallThumbUrl(item.id);
      };
      const applyArchivedCover = records => {
        records = Array.isArray(records) ? records.filter(record => record.blob?.type?.startsWith('image/')) : [];
        if (mediaGeneration !== mediaCacheGeneration || cachedPrivateSession || !media.isConnected || !Array.isArray(records) || !records.length) return;
        const record = records.find(entry => entry.isCustomCover) || records.find(entry => entry.kind === 'snapshot') || records[0];
        const key = `${record.mediaId}:${record.coverUpdatedAt || 0}:${record.capturedAt || 0}`;
        if (key === currentCoverKey) return;
        const objectUrl = RoomGridModelMedia.objectUrl(record);
        if (!objectUrl) return;
        const revision = ++coverRevision;
        const preload = new Image();
        preload.onerror = () => { URL.revokeObjectURL(objectUrl); usePublicThumbnail(); };
        preload.onload = () => {
          if (revision !== coverRevision || mediaGeneration !== mediaCacheGeneration || cachedPrivateSession || !media.isConnected) { URL.revokeObjectURL(objectUrl); return; }
          currentCoverKey = key;
          img.dataset.coverFallback = 'generated-local';
          // The probe is eager; keep the card image eager too so off-screen
          // removals do not leave a lazy blob URL alive indefinitely.
          img.loading = 'eager';
          img.addEventListener('load', () => setTimeout(() => URL.revokeObjectURL(objectUrl), 0), { once: true });
          img.src = objectUrl;
          modelCoverCache.delete(item.id);
          modelCoverCache.set(item.id, record);
          let bytes = [...modelCoverCache.values()].reduce((sum, entry) => sum + (entry.blob?.size || 0), 0);
          while (modelCoverCache.size > 96 || bytes > 32 * 1024 * 1024) {
            const oldest = modelCoverCache.keys().next().value;
            bytes -= modelCoverCache.get(oldest)?.blob?.size || 0;
            modelCoverCache.delete(oldest);
          }
          media.dataset.roomgridMediaSource = record.isCustomCover ? 'local-custom-cover' : 'local-public-preview-archive';
          sourceLabel?.classList.add('is-archived');
          if (sourceLabel) sourceLabel.textContent = record.isCustomCover
            ? tx(`自己的封面 · ${dateTime(record.capturedAt)}`, `Custom cover · ${dateTime(record.capturedAt)}`, `Eigenes Cover · ${dateTime(record.capturedAt)}`)
            : tx(
              `本地保存的封面 · ${dateTime(record.capturedAt)}`,
              `Locally saved cover · ${dateTime(record.capturedAt)}`,
              `Lokal gespeichertes Cover · ${dateTime(record.capturedAt)}`,
              `Portada guardada localmente · ${dateTime(record.capturedAt)}`,
              `Capa salva localmente · ${dateTime(record.capturedAt)}`,
            );
        };
        preload.src = objectUrl;
      };
      // Read the existing cover as soon as the card is attached. Only new
      // network captures/compression wait for idle time; a local cover must not.
      const archiveReady = Promise.resolve().then(async () => {
        if (cachedPrivateSession) { usePublicThumbnail(); return []; }
        if (mediaGeneration !== mediaCacheGeneration || !media.isConnected) return [];
        const existingCover = modelCoverCache.get(item.id);
        if (existingCover?.isCustomCover || (existingCover && Date.now() - Number(existingCover.capturedAt || 0) < 5 * 60 * 1000)) return [existingCover];
        const archived = await RoomGridModelMedia.list(item.id);
        applyArchivedCover(archived);
        if (cachedPrivateSession || mediaGeneration !== mediaCacheGeneration) return [];
        if (!archived.some(record => record.blob?.type?.startsWith('image/'))) usePublicThumbnail();
        return archived;
      });
      queueMediaHydration(media, async () => {
        const archived = await archiveReady;
        if (cachedPrivateSession || mediaGeneration !== mediaCacheGeneration || !media.isConnected) return;
        applyArchivedCover(archived);
        if (archived.some(record => record.isCustomCover)) return;
        const captured = await RoomGridModelMedia.capturePack(item.id, { live: libraryStatusBucket(item) === 'live', urls: saved });
        applyArchivedCover(captured);
      });
      // Reuse a previously decoded cover on background re-renders; do not wait
      // for another IndexedDB/network capture cycle before displaying it.
      const cachedCover = modelCoverCache.get(item.id);
      if (cachedCover && !cachedPrivateSession) queueMicrotask(() => applyArchivedCover([cachedCover]));
      return media;
    }

    function modelExampleGallery(item) {
      const grid = $('div', { class: 'rgh-example-gallery-grid' });
      const summary = $('summary', {}, tx('示例图片和封面', 'Example images and covers', 'Beispielbilder und Cover', 'Imágenes de ejemplo y portadas', 'Imagens de exemplo e capas'));
      const status = $('span', { class: 'rgh-example-gallery-status' }, tx('正在读取本地图片档案…', 'Reading local image archive…', 'Lokales Bildarchiv wird gelesen …', 'Leyendo el archivo de imágenes local…', 'Lendo o arquivo de imagens local…'));
      const saveButton = $('button', { class: 'rgh-example-gallery-save', type: 'button' }, tx('保存新快照', 'Save new snapshot', 'Neue Momentaufnahme speichern', 'Guardar nueva instantánea', 'Salvar novo instantâneo'));
      const details = $('details', { class: 'rgh-example-gallery', dataset: { roomgridExampleGallery: item.id } }, [
        summary,
        $('div', { class: 'rgh-example-gallery-controls' }, [status, saveButton]),
        grid,
      ]);
      let loadRevision = 0;
      let openedOnce = false;
      const renderImages = async ({ capture = false, force = false } = {}) => {
        const revision = ++loadRevision;
        saveButton.disabled = capture;
        if (capture) status.textContent = tx('正在保存公开预览…', 'Saving public previews…', 'Öffentliche Vorschaubilder werden gespeichert …', 'Guardando vistas previas públicas…', 'Salvando prévias públicas…');
        let archived = await RoomGridModelMedia.list(item.id);
        if (capture) archived = await RoomGridModelMedia.capturePack(item.id, { force, live: libraryStatusBucket(item) === 'live', urls: item.model.previewUrls || [] });
        archived = archived.filter(record => record.blob?.type?.startsWith('image/'));
        if (revision !== loadRevision || !details.isConnected) return;
        saveButton.disabled = false;
        summary.textContent = tx(
          `示例图片和封面（已保存 ${archived.length} 张）`,
          `Example images and covers (${archived.length} saved)`,
          `Beispielbilder und Cover (${archived.length} gespeichert)`,
          `Imágenes y portadas (${archived.length} guardadas)`,
          `Imagens e capas (${archived.length} salvas)`,
        );
        status.textContent = archived.length
          ? tx(
            `永久保存在此设备上 · 最近 ${dateTime(archived[0].capturedAt)}`,
            `Permanently stored on this device · latest ${dateTime(archived[0].capturedAt)}`,
            `Dauerhaft auf diesem Gerät · zuletzt ${dateTime(archived[0].capturedAt)}`,
            `Guardadas en este dispositivo · última ${dateTime(archived[0].capturedAt)}`,
            `Salvas neste dispositivo · última ${dateTime(archived[0].capturedAt)}`,
          )
          : tx('尚未保存图片；当前公开预览仍会显示。', 'No saved image yet; current public previews are still shown.', 'Noch kein Bild gespeichert; aktuelle öffentliche Vorschauen werden trotzdem angezeigt.', 'Aún no hay imágenes guardadas; se muestran las vistas públicas actuales.', 'Ainda não há imagens salvas; as prévias públicas atuais continuam visíveis.');
        const sources = [];
        const addSource = (url, label, archivedImage = false) => { if (url && !sources.some(entry => entry.url === url)) sources.push({ url, label, archivedImage }); };
        archived.slice(0, 6).forEach((record, index) => addSource(RoomGridModelMedia.objectUrl(record), record.isCustomCover
          ? tx(`自己的封面 · ${dateTime(record.capturedAt)}`, `Custom cover · ${dateTime(record.capturedAt)}`, `Eigenes Cover · ${dateTime(record.capturedAt)}`)
          : record.userOwned
            ? tx(`自己的图片 · ${dateTime(record.capturedAt)}`, `Own image · ${dateTime(record.capturedAt)}`, `Eigenes Bild · ${dateTime(record.capturedAt)}`)
            : tx(
              `已保存的${record.kind === 'cover' ? '封面' : '快照'} ${archived.length - index} · ${dateTime(record.capturedAt)}`,
              `Saved ${record.kind === 'cover' ? 'cover' : 'snapshot'} ${archived.length - index} · ${dateTime(record.capturedAt)}`,
              `Gespeichertes ${record.kind === 'cover' ? 'Cover' : 'Beispielbild'} ${archived.length - index} · ${dateTime(record.capturedAt)}`,
              `${record.kind === 'cover' ? 'Portada' : 'Instantánea'} guardada · ${dateTime(record.capturedAt)}`,
              `${record.kind === 'cover' ? 'Capa' : 'Instantâneo'} salvo · ${dateTime(record.capturedAt)}`,
            ), true));
        if (sources.length < 3) {
          addSource(thumbUrl(item.id), tx('当前公开封面', 'Current public cover', 'Aktuelles öffentliches Cover', 'Portada pública actual', 'Capa pública atual'));
          addSource(smallThumbUrl(item.id), tx('当前紧凑预览', 'Current compact preview', 'Aktuelle kompakte Vorschau', 'Vista compacta actual', 'Prévia compacta atual'));
        }
        if (libraryStatusBucket(item) === 'live') addSource(liveFrameUrl(item.id), tx('当前实时画面', 'Current live image', 'Aktuelles Livebild', 'Imagen en vivo actual', 'Imagem ao vivo atual'));
        grid.replaceChildren(...sources.slice(0, 6).map(({ url, label, archivedImage }) => {
          const image = $('img', { src: url, alt: `${item.id} – ${label || tx('预览', 'Preview', 'Vorschau', 'Vista previa', 'Prévia')}`, loading: 'lazy', referrerPolicy: 'no-referrer' });
          if (archivedImage) image.addEventListener('load', () => setTimeout(() => URL.revokeObjectURL(url), 0), { once: true });
          image.addEventListener('error', () => {
            if (!archivedImage && !image.dataset.fallback) { image.dataset.fallback = '1'; image.src = thumbUrl(item.id); }
            else image.classList.add('is-error');
          });
          return $('div', { class: `rgh-example-shot${archivedImage ? ' is-archived' : ''}` }, [image, $('span', {}, label)]);
        }));
      };
      details.addEventListener('toggle', () => {
        if (!details.open) return;
        const firstOpen = !openedOnce;
        openedOnce = true;
        renderImages({ capture: firstOpen, force: firstOpen }).catch(() => {});
      });
      saveButton.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); renderImages({ capture: true, force: true }).catch(() => {}); });
      return details;
    }

    function modelActions(item, includeLibrary = false) {
      const room = item.room;
      const ensureRoom = () => { if (!activeStore.state.rooms.some(entry => entry.id === item.id)) activeStore.addRoom(item.id); };
      const favorite = () => { ensureRoom(); const current = activeStore.state.rooms.find(entry => entry.id === item.id); if (!isFavorite(current)) activeStore.toggleRoomInGroup(item.id, FAVORITE_GROUP_ID); else activeStore.toggleRoomInGroup(item.id, FAVORITE_GROUP_ID); };
      return $('div', { class: 'rgh-actions' }, [
        action(tx('房间', 'Room', 'Raum öffnen'), () => openNoopener(roomGridSingleCamUrl(item.id, { source: 'hub' })), 'primary'),
        action(tx('详情', 'Details', 'Alle Details'), () => RoomGridUltimate.openInspector(item.id)),
        $('details', { class: 'rgh-action-more' }, [
          $('summary', { class: 'rgh-action', role: 'button' }, tx('更多', 'More', 'Mehr')),
          $('div', { class: 'rgh-action-menu' }, [
            action(tx('固定预览', 'Pin preview', 'Vorschau anheften'), () => RoomGridUltimate.openPreview(item.id)),
            action(RoomGridUltimate.comparisonStatus().ids.includes(item.id) ? tx('从比较中移除', 'Remove from comparison', 'Aus Vergleich entfernen') : tx('加入比较', 'Add to comparison', 'Zum Vergleich'), () => RoomGridUltimate.toggleCompare(item.id), RoomGridUltimate.comparisonStatus().ids.includes(item.id) ? 'active' : ''),
            action(isFavorite(room) ? `★ ${tx('收藏', 'Favorite', 'Favorit')}` : `☆ ${tx('收藏', 'Favorite', 'Favorit')}`, favorite, isFavorite(room) ? 'active' : ''),
            !room ? action('MultiCam +', () => activeStore.addRoom(item.id)) : null,
            includeLibrary && room ? action(room.watchlist ? tx('取消观察', 'Unwatch', 'Merkliste aus') : tx('观察列表', 'Watchlist', 'Merkliste'), () => activeStore.patchRoom(item.id, { watchlist: !room.watchlist }), room.watchlist ? 'active' : '') : null,
          ]),
        ]),
      ]);
    }

    function lineageRow(item) {
      const sources = RoomGridDataProvenance.itemSources(item);
      const freshness = RoomGridDataProvenance.freshness(item);
      return $('div', { class: 'rgh-lineage', dataset: { roomgridLineage: item.id }, ariaLabel: tx('数据来源和新鲜度', 'Data sources and freshness', 'Datenquellen und Aktualität') }, [
        ...sources.map(source => $('span', { dataset: { tone: source.tone }, title: tx('数据来源', 'Data source', 'Datenquelle') }, rawUiText(source.label))),
        $('span', { dataset: { tone: freshness.tone }, title: freshness.at ? dateTime(freshness.at) : tx('时间未知', 'Time unknown', 'Zeitpunkt unbekannt') }, rawUiText(freshness.label)),
      ]);
    }

    function datasetScope(data, matching, shown, page, pageSize) {
      const allCoverage = RoomGridDataProvenance.coverage(data.items);
      const matchCoverage = RoomGridDataProvenance.coverage(matching);
      const start = matching.length ? (Math.max(1, page) - 1) * pageSize + 1 : 0;
      const end = matching.length ? Math.min(matching.length, start + shown.length - 1) : 0;
      const lastAt = data.items.reduce((latest, item) => Math.max(latest, Number(item.model?.lastObservedAt) || 0, Number(item.lastActivity) || 0), 0);
      const percent = value => allCoverage.total ? `${Math.round(value / allCoverage.total * 100)} %` : '0 %';
      const chips = [
        [tx('完整本地数据集', 'Full local data set', 'Vollständiger lokaler Datenbestand'), allCoverage.total],
        [tx('符合筛选', 'Matching filters', 'Passend zum Filter'), matchCoverage.total],
        [tx('此页显示', 'Shown on this page', 'Auf dieser Seite'), `${start}–${end}`],
        [tx('个人整理', 'Personally organized', 'Persönlich organisiert'), allCoverage.saved],
        [tx('最近直播信号', 'Latest live signals', 'Letzte Live-Signale'), allCoverage.live],
        [tx('有观看记录', 'With watch history', 'Mit Sehverlauf'), allCoverage.watched],
        [tx('公开资料覆盖', 'Public-profile coverage', 'Profilabdeckung'), percent(allCoverage.profile)],
        [tx('国家覆盖', 'Country coverage', 'Länderabdeckung'), percent(allCoverage.country)],
        [tx('年龄覆盖', 'Age coverage', 'Altersabdeckung'), percent(allCoverage.age)],
        [tx('标签覆盖', 'Tag coverage', 'Tag-Abdeckung'), percent(allCoverage.tags)],
      ];
      return $('section', { class: 'rgh-dataset-scope', dataset: { roomgridDatasetScope: '1' } }, [
        $('div', { class: 'rgh-dataset-scope-head' }, [
          $('strong', {}, tx('正在搜索哪个数据集？', 'Which data set is being searched?', 'Welcher Datenbestand wird durchsucht?')),
          $('span', {}, lastAt ? `${tx('最后一次本地观察', 'Last local observation', 'Letzte lokale Beobachtung')}: ${dateTime(lastAt)}` : tx('尚无观察时间', 'No observation time yet', 'Noch kein Beobachtungszeitpunkt')),
        ]),
        $('div', { class: 'rgh-dataset-chips' }, chips.slice(0, 3).map(([label, value]) => $('span', { class: 'rgh-dataset-chip' }, [$('b', {}, String(value)), rawUiText(label)]))),
        $('details', { class: 'rgh-source-details' }, [
          $('summary', {}, tx('数据来源与覆盖率', 'Data sources and coverage', 'Datenquellen und Abdeckung')),
          $('div', { class: 'rgh-dataset-chips' }, chips.slice(3).map(([label, value]) => $('span', { class: 'rgh-dataset-chip' }, [$('b', {}, String(value)), rawUiText(label)]))),
          $('p', { class: 'rgh-source-legend' }, tx('公共 = 来自当前 Chaturbate 页面或实时目录。个人 = 由你保存、标记或分组。本地 = 仅在此设备上观察到的会话、预览或质量值。未知字段保持未知，不会被猜测。', 'Public = from current Chaturbate pages or live catalog. Personal = saved, tagged or grouped by you. Local = sessions, previews or quality values observed only on this device. Unknown fields remain unknown and are never guessed.', 'Öffentlich = aus aktuellen Chaturbate-Seiten oder dem Livekatalog. Persönlich = von dir gespeichert, markiert oder gruppiert. Lokal = nur auf diesem Gerät beobachtete Sitzungen, Vorschauen oder Qualitätswerte. Unbekannte Felder bleiben unbekannt und werden nicht geraten.')),
        ]),
      ]);
    }

