      const balancedKeys = ['libraryShowImage', 'libraryShowBio', 'libraryShowCatalogBadge', 'libraryShowStatus', 'libraryShowViewers', 'libraryShowCountry', 'libraryShowLocation', 'libraryShowAge', 'libraryShowType', 'libraryShowWatchTime', 'libraryShowSessions', 'libraryShowAverageSession', 'libraryShowLastSeen', 'libraryShowLastLive', 'libraryShowOnlineEstimate', 'libraryShowGroups', 'libraryShowPublicTags', 'libraryShowRating', 'libraryShowActions'];
