    function createTagEditor(room, tagSuggestions, pendingInput = '', onDraftChange = null) {
      let draft = [...new Set((room.localTags || []).map(tag => String(tag).trim().toLocaleLowerCase()).filter(Boolean))];
      const editorTags = value => [...new Set(String(value || '').split(/[,;\n]+/u).map(tag => tag.trim().toLocaleLowerCase().slice(0, 50)).filter(Boolean))];
      const chips = $('div', { class: 'rgh-tag-editor-chips' });
      const matches = $('div', { class: 'rgh-tag-suggestions' });
      const input = $('input', { class: 'rgh-tag-input', type: 'text', value: pendingInput, dataset: { libraryDraftField: 'tags' }, ariaLabel: `${tx('自己的标签', 'Own tags', 'Eigene Tags')} · ${room.id}`, placeholder: 'Eigenen Tag eingeben …', autocomplete: 'off' });
      const tagNotice = $('small', { role: 'status', dataset: { tagLimitNotice: '1' } });
      const remember = () => onDraftChange?.({ localTags: [...draft], tagInput: input.value });
      const drawChips = () => chips.replaceChildren(...(draft.length ? draft.map(tag => $('button', { type: 'button', title: tx(`删除标签 ${tag}`, `Remove tag ${tag}`, `Tag ${tag} entfernen`, `Eliminar etiqueta ${tag}`, `Remover tag ${tag}`), onclick: () => { draft = draft.filter(value => value !== tag); remember(); drawChips(); drawMatches(input.value); } }, rawUiText(`#${tag} ×`))) : [$('span', {}, tx('还没有自定义标签', 'No custom tags yet', 'Noch keine eigenen Tags', 'Todavía no hay etiquetas propias', 'Ainda não há tags próprias'))]));
      const addValues = value => {
        const additions = editorTags(value);
        if (!additions.length) return false;
        const next = [...new Set([...draft, ...additions])];
        if (next.length > Math.max(40, draft.length)) {
          tagNotice.textContent = tx('最多40个自定义标签。请先删除一个；输入内容已保留。', 'Up to 40 own tags. Remove one first; your input has been kept.', 'Bis zu 40 eigene Tags. Entferne zuerst einen; deine Eingabe bleibt erhalten.');
          remember(); return false;
        }
        tagNotice.textContent = ''; draft = next;
        input.value = '';
        remember();
        drawChips();
        matches.replaceChildren();
        return true;
      };
      const drawMatches = value => {
        const query = String(value || '').trim().toLocaleLowerCase();
        const options = (tagSuggestions || []).filter(item => !draft.includes(item.tag) && (!query || item.tag.includes(query))).slice(0, 8);
        matches.replaceChildren(...options.map(item => $('button', { type: 'button', onclick: () => { addValues(item.tag); input.focus(); } }, [$('b', {}, `#${item.tag}`), $('span', {}, tx(`${item.count} 个模型`, `${item.count} model${item.count === 1 ? '' : 's'}`, `${item.count} Model${item.count === 1 ? '' : 's'}`, `${item.count} modelo${item.count === 1 ? '' : 's'}`, `${item.count} modelo${item.count === 1 ? '' : 's'}`))])));
        matches.classList.toggle('is-open', !!query && options.length > 0);
      };
      input.addEventListener('input', () => { remember(); drawMatches(input.value); });
      input.addEventListener('focus', () => drawMatches(input.value));
      input.addEventListener('keydown', event => {
        if (event.key === 'Enter' || event.key === ',') { event.preventDefault(); addValues(input.value); }
        if (event.key === 'Escape') matches.classList.remove('is-open');
      });
      input.addEventListener('blur', () => setTimeout(() => matches.classList.remove('is-open'), 140));
      drawChips();
      return {
        element: $('section', { class: 'rgh-tag-editor' }, [
          $('div', { class: 'rgh-editor-label' }, [$('strong', {}, 'Eigene Tags'), $('span', {}, 'lokal · für Suche und Filter')]),
          chips,
          $('div', { class: 'rgh-tag-entry' }, [input, action('Tag hinzufügen', () => addValues(input.value))]),
          matches, tagNotice,
          $('small', {}, 'Enter oder „Tag hinzufügen“ übernimmt den Entwurf. Dauerhaft gespeichert wird er erst mit „Profil speichern“. Bereits verwendete Tags werden beim Tippen vorgeschlagen.'),
        ]),
        values: () => { const next = [...new Set([...draft, ...editorTags(input.value)])]; if (next.length > Math.max(40, draft.length)) { addValues(input.value); return null; } return next; },
      };
    }

    function groupPicker(item, groups) {
      const room = activeStore.state.rooms.find(entry => entry.id === item.id) || item.room || null;
      const assigned = groups.filter(group => roomInGroup(room, group.id));
      const ensureOrganizedRoom = () => {
        let current = activeStore.state.rooms.find(entry => entry.id === item.id);
        if (!current) { activeStore.addRoom(item.id); current = activeStore.state.rooms.find(entry => entry.id === item.id); }
        return current;
      };
      const picker = $('details', { class: 'rgh-group-picker', open: openLibraryGroupPickers.has(item.id), dataset: { roomgridGroupPicker: item.id } }, [
        $('summary', {}, tx(`管理自定义组 · 已分配到 ${assigned.length} 个`, `Manage custom groups · assigned to ${assigned.length}`, `Eigene Gruppen verwalten · ${assigned.length} zugeordnet`, `Administrar grupos propios · asignado a ${assigned.length}`, `Gerenciar grupos próprios · atribuído a ${assigned.length}`)),
        $('div', { class: 'rgh-group-picker-list' }, groups.length ? groups.map(group => $('label', {}, [
          $('input', { type: 'checkbox', checked: roomInGroup(room, group.id), onchange: event => {
            const current = ensureOrganizedRoom();
            if (!!current && roomInGroup(current, group.id) !== event.target.checked) activeStore.toggleRoomInGroup(item.id, group.id);
          } }),
          $('span', {}, rawUiText(group.name)),
        ])) : [$('span', { class: 'rgh-muted-copy' }, 'Erstelle oben zuerst eine eigene Gruppe.')]),
      ]);
      picker.addEventListener('toggle', () => {
        if (!picker.isConnected) return;
        if (picker.open) openLibraryGroupPickers.add(item.id); else openLibraryGroupPickers.delete(item.id);
      });
      return picker;
    }

