    function statsActiveFilterCount() {
      let count = Object.entries(STATS_FILTER_DEFAULTS).reduce((total, [key, fallback]) => {
        const value = viewState[key];
        if (Array.isArray(fallback)) return total + (Array.isArray(value) && value.length ? 1 : 0);
        return total + (value !== fallback ? 1 : 0);
      }, 0);
      if (viewState.status !== 'all') count += 1;
      if (viewState.savedOnly) count += 1;
      if (viewState.query) count += 1;
      return count;
    }

    function matchesStatsAdvancedFilters(item) {
      const model = item.model || {};
      const room = item.room || null;
      const gender = ['f', 'm', 'c', 't'].includes(String(model.gender || '')) ? String(model.gender) : 'unknown';
      const country = String(model.country || '').trim();
      const age = Math.max(0, Number(model.age) || 0);
      const viewers = Math.max(0, Number(model.viewerCount) || 0);
      const followers = Math.max(0, Number(model.followers) || 0);
      const groups = getRoomGroups(room);
      const ownTags = room?.localTags || [];
      const hasNotes = !!String(room?.notes || '').trim();
      const hasSavedMedia = !!(model.previewUrls || []).filter(Boolean).length;
      if (viewState.statsGenders.length && !viewState.statsGenders.includes(gender)) return false;
      if (viewState.statsCountries.length && !viewState.statsCountries.includes(country)) return false;
      if (viewState.statsPublicTags.length) {
        const publicTags = new Set(publicTagsForLibraryItem(item));
        const matches = viewState.statsPublicTags.map(tag => publicTags.has(tag));
        if (viewState.statsPublicTagMode === 'all' ? !matches.every(Boolean) : !matches.some(Boolean)) return false;
      }
      if (viewState.statsGroups.length) {
        const matches = viewState.statsGroups.map(id => groups.includes(id));
        if (viewState.statsGroupMode === 'all' ? !matches.every(Boolean) : !matches.some(Boolean)) return false;
      }
      if ((viewState.statsAgeMin || viewState.statsAgeMax) && !age) return false;
      if (viewState.statsAgeMin && age < viewState.statsAgeMin) return false;
      if (viewState.statsAgeMax && age > viewState.statsAgeMax) return false;
      if (viewState.statsViewerMin && viewers < viewState.statsViewerMin) return false;
      if (viewState.statsViewerMax && viewers > viewState.statsViewerMax) return false;
      if (viewState.statsFollowersMin && followers < viewState.statsFollowersMin) return false;
      if (viewState.statsFollowersMax && followers > viewState.statsFollowersMax) return false;
      if (viewState.statsWatchMinMinutes && item.totalMs < viewState.statsWatchMinMinutes * 60000) return false;
      if (viewState.statsWatchMaxMinutes && item.totalMs > viewState.statsWatchMaxMinutes * 60000) return false;
      if (viewState.statsSessionsMin && item.sessions < viewState.statsSessionsMin) return false;
      if (viewState.statsSessionsMax && item.sessions > viewState.statsSessionsMax) return false;
      if (viewState.statsActiveDaysMin && item.activeDays < viewState.statsActiveDaysMin) return false;
      if (viewState.statsPreviewsMin && Number(item.counts.preview || 0) < viewState.statsPreviewsMin) return false;
      if (viewState.statsQuickViewsMin && Number(item.counts.quickview || 0) < viewState.statsQuickViewsMin) return false;
      if (viewState.statsRatingMin && Number(room?.rating || 0) < viewState.statsRatingMin) return false;
      if (viewState.statsPriorityMin && Number(room?.priority || 0) < viewState.statsPriorityMin) return false;
      if (viewState.statsAppearancesMin && Number(model.appearances || 0) < viewState.statsAppearancesMin) return false;
      if (viewState.statsOnlineSamplesMin && Number(model.onlineSamples || 0) < viewState.statsOnlineSamplesMin) return false;
      if (viewState.statsActivityDays && (!item.lastActivity || item.lastActivity < Date.now() - viewState.statsActivityDays * 86400000)) return false;
      if (viewState.statsOrganization === 'organized' && !room) return false;
      if (viewState.statsOrganization === 'catalog' && room) return false;
      if (viewState.statsProfileState === 'loaded' && !item.profile) return false;
      if (viewState.statsProfileState === 'missing' && item.profile) return false;
      if (viewState.statsWatchState === 'watched' && item.totalMs <= 0) return false;
      if (viewState.statsWatchState === 'unwatched' && item.totalMs > 0) return false;
      if (viewState.statsMediaState === 'saved' && !hasSavedMedia) return false;
      if (viewState.statsMediaState === 'missing' && hasSavedMedia) return false;
      if (viewState.statsMediaState === 'live' && libraryStatusBucket(item) !== 'live') return false;
      if (viewState.statsOwnTagsState === 'with' && !ownTags.length) return false;
      if (viewState.statsOwnTagsState === 'without' && ownTags.length) return false;
      if (viewState.statsGroupsState === 'with' && !groups.length) return false;
      if (viewState.statsGroupsState === 'without' && groups.length) return false;
      if (viewState.statsNotesState === 'with' && !hasNotes) return false;
      if (viewState.statsNotesState === 'without' && hasNotes) return false;
      const isHd = !!model.isHd;
      const isGaming = !!model.isGaming;
      if (viewState.statsFeature === 'hd' && !isHd) return false;
      if (viewState.statsFeature === 'gaming' && !isGaming) return false;
      if (viewState.statsFeature === 'both' && (!isHd || !isGaming)) return false;
      if (viewState.statsFeature === 'neither' && (isHd || isGaming)) return false;
      return true;
    }

