            ...Object.entries(genderLabels).map(([value, label]) => $('button', { class: `rgh-filter-toggle${viewState.statsGenders.includes(value) ? ' is-active' : ''}`, type: 'button', ariaPressed: String(viewState.statsGenders.includes(value)), onclick: () => toggleGender(value) }, [label, $('b', {}, compactNumber(genderCounts[value] || 0))])),
