    // Attach each card before yielding: cover hydration runs in microtasks and
    // deliberately skips detached media. Keep the grid connected while small
    // batches give input/navigation a turn instead of constructing 72 editors
    // in one long task. An old render must never append to the newer page.
    async function appendHubCards(target, className, shown, createCard, revision, emptyText) {
      const grid = $('div', { class: className });
      target.appendChild(grid);
      if (!shown.length) {
        grid.appendChild($('div', { class: 'rgh-empty' }, emptyText));
        return true;
      }
      let sliceStartedAt = performance.now();
      for (let index = 0; index < shown.length; index += 1) {
        if (revision !== renderRevision || !grid.isConnected) return false;
        grid.appendChild(createCard(shown[index]));
        if (index + 1 < shown.length && (index + 1) % 4 === 0 && performance.now() - sliceStartedAt >= 8) {
          await yieldToUi();
          sliceStartedAt = performance.now();
        }
      }
      return revision === renderRevision && grid.isConnected;
    }

    function pagination(total, current, setter, pageSize = viewState.pageSize) {
      const pages = Math.max(1, Math.ceil(total / pageSize));
      const page = Math.max(1, Math.min(pages, current));
      return $('div', { class: 'rgh-pagination' }, [
        action('‹ Zurück', () => { setter(Math.max(1, page - 1)); scheduleRender(true); }, page <= 1 ? 'disabled' : ''),
        $('span', {}, tx(`第 ${page} 页，共 ${pages} 页 · ${compactNumber(total)} 个模型`, `Page ${page} of ${pages} · ${compactNumber(total)} models`, `Seite ${page} von ${pages} · ${compactNumber(total)} Models`, `Página ${page} de ${pages} · ${compactNumber(total)} modelos`, `Página ${page} de ${pages} · ${compactNumber(total)} modelos`)),
        action('Weiter ›', () => { setter(Math.min(pages, page + 1)); scheduleRender(true); }, page >= pages ? 'disabled' : ''),
      ]);
    }

