        gender: (a, b) => String(a.model.gender || 'unknown').localeCompare(String(b.model.gender || 'unknown')) || a.id.localeCompare(b.id),
        tag_count: (a, b) => publicTagsForLibraryItem(b).length - publicTagsForLibraryItem(a).length || a.id.localeCompare(b.id),
        group_count: (a, b) => getRoomGroups(b.room).length - getRoomGroups(a.room).length || a.id.localeCompare(b.id),
        quality: (a, b) => qualityScore(b) - qualityScore(a) || b.samples.length - a.samples.length,
