    let modelHeatCache = null;
    async function prepareModelHeat(models, revision) {
      const dataRevision = analytics.getDataRevision();
      if (modelHeatCache?.dataRevision === dataRevision && modelHeatCache.modelCount === models.length && analytics.isReady?.() !== false) return modelHeatCache.heat;
      const heat = Array(168).fill(0);
      let sliceAt = performance.now();
      for (const model of models) {
        (model.hours || []).forEach((value, index) => { heat[index] += Number(value) || 0; });
        if (performance.now() - sliceAt >= 8) {
          await new Promise(resolve => setTimeout(resolve, 0));
          if (revision !== renderRevision || tab !== 'analytics') return null;
          sliceAt = performance.now();
        }
      }
      // A partial or superseded calculation must never become a warm result.
      if (revision !== renderRevision || tab !== 'analytics') return null;
      if (analytics.getDataRevision() === dataRevision && analytics.isReady?.() !== false) modelHeatCache = { dataRevision, modelCount: models.length, heat };
      return heat;
    }

    let plannerCache = null;
    async function prepareOnlinePlanner(models, revision) {
      const now = new Date();
      const hourKey = Math.floor(now.getTime() / 3600000);
      const dataRevision = analytics.getDataRevision();
      if (plannerCache?.hourKey === hourKey && plannerCache.dataRevision === dataRevision && plannerCache.modelCount === models.length && analytics.isReady?.() !== false) return plannerCache.items;
      const currentIndex = now.getDay() * 24 + now.getHours();
      const items = [];
      let sliceAt = performance.now();
      for (const model of models) {
        let observedTotal = 0;
        const observedHours = model.onlineHours;
        const observedHourCount = Array.isArray(observedHours) ? Math.min(168, observedHours.length) : observedHours ? 168 : 0;
        for (let index = 0; index < observedHourCount; index += 1) observedTotal += Math.max(0, Number(observedHours[index]) || 0);
        const weights = observedTotal > 0 ? model.onlineHours : model.hours;
        let best = { offset: 0, score: 0 };
        for (let offset = 0; offset < 48; offset += 1) {
          const score = Math.max(0, Number(weights?.[(currentIndex + offset) % 168]) || 0);
          if (score > best.score) best = { offset, score };
        }
        if (best.score > 0) items.push({ model, best, samples: Math.max(Number(model.onlineSamples || 0), observedTotal) });
        if (performance.now() - sliceAt >= 8) {
          await new Promise(resolve => setTimeout(resolve, 0));
          if (revision !== renderRevision || tab !== 'analytics') return null;
          sliceAt = performance.now();
        }
      }
      items.sort((a, b) => b.best.score - a.best.score || b.samples - a.samples);
      const result = items.slice(0, 40);
      if (analytics.getDataRevision() === dataRevision && analytics.isReady?.() !== false) plannerCache = { hourKey, dataRevision, modelCount: models.length, items: result };
      return result;
    }

