      const capabilityScore = Object.values(capabilities).filter(Boolean).length / Math.max(1, Object.keys(capabilities).length);
      const healthScore = Math.max(0, Math.min(100, Math.round((okChecks / Math.max(1, checks.length)) * 70 + capabilityScore * 25 + (errorRows.length ? Math.max(0, 5 - errorRows.length) : 5))));
