    let storeUnsubscribe = null;
    let previousCatalogVisitAt = state.lastCatalogVisitAt || 0;
    let singleContextIds = state.singleContext.slice();
    let singleReturnView = state.singleReturnView;
    let singleSession = null;
    let singleAnalyticsRefresh = null;
    let commandPalette = null;
    let pendingScrollRestore = true;
    let pendingFilterFocus = null;
    let filterRenderTimer = 0;
    let backgroundRenderTimer = 0;
    let tagSuggestionCache = { signature: '', values: [] };
    let discoverInterestProfileCache = { signature: '', value: null };
    let activeCardMoreClose = null;
    const profileChanges = new Map();
    const publicProfileRequests = new Map();
    const publicProfileRetryAt = new Map();
    const PUBLIC_PROFILE_FRESH_MS = 6 * 60 * 60 * 1000;
    const viewDomCache = new Map();
    let activeVisualSignature = '';
    let catalogDataRevision = 0;
    let localMetadataRevision = 0;
    let observationsRevision = 0;
    let statsRevision = -1;
    let roomsIndexRevision = -1;
    let roomsById = new Map();
