    function createSavedRow(kind) {
      const isFeed = kind === 'feed';
      const list = isFeed ? state.feeds : state.profiles;
      const activeId = isFeed ? state.activeFeedId : state.activeProfileId;
      const select = $('select', { class: 'discover-input' }, [
        $('option', { value: '' }, isFeed ? tx('未选择动态', 'No feed selected', 'Kein Feed ausgewählt') : tx('未选择视图', 'No view selected', 'Keine Ansicht ausgewählt')),
        ...list.map(item => $('option', { value: item.id }, rawUiText(item.name))),
      ]);
      select.value = list.some(item => item.id === activeId) ? activeId : '';
      const applyButton = $('button', { class: 'discover-btn', type: 'button', disabled: !select.value, onclick: () => applyDefinition(list.find(item => item.id === select.value), isFeed) }, tx('应用', 'Apply', 'Anwenden'));
      const deleteButton = $('button', { class: 'discover-btn danger', type: 'button', disabled: !select.value, onclick: () => deleteNamed(kind, select.value) }, tx('删除', 'Delete', 'Löschen'));
      select.addEventListener('change', () => { applyButton.disabled = deleteButton.disabled = !select.value; });
      return $('div', { class: 'discover-saved-row' }, [
        filterField(isFeed ? tx('保存的动态', 'Saved feeds', 'Gespeicherte Feeds') : tx('保存的视图', 'Saved views', 'Gespeicherte Ansichten'), select),
        $('button', { class: 'discover-btn primary', type: 'button', onclick: () => saveNamed(kind) }, tx('新保存', 'Save new', 'Neu speichern')),
        applyButton,
        deleteButton,
      ]);
    }

    function createPreviewControls(homepage = false) {
      const previewEnabled = $('input', { type: 'checkbox', checked: state.previewEnabled });
      previewEnabled.addEventListener('change', () => { state.previewEnabled = previewEnabled.checked; persistDiscoverState(); previewScheduler.refresh(); });
      const previewFps = selectControl(String(state.previewFps), [['0', tx('关闭', 'Off', 'Aus')], ['0.1', '0,1 FPS · 10 s'], ['0.2', '0,2 FPS · 5 s'], ['0.25', '0,25 FPS · 4 s'], ['0.33', '0,33 FPS · 3 s'], ['0.5', '0,5 FPS · 2 s'], ['0.75', '0,75 FPS'], ['1', '1 FPS'], ['1.5', '1,5 FPS'], ['2', '2 FPS'], ['3', '3 FPS'], ['4', '4 FPS'], ['5', '5 FPS'], ...PREVIEW_FPS_VALUES.filter(fps => fps > 5).map(fps => [String(fps), `${fps} FPS${fps === 240 ? ' · MAX' : ''}`])], value => {
        state.previewFps = Number(value); state.previewEnabled = Number(value) > 0; persistDiscoverState(); previewScheduler.refresh(); renderCurrentView();
      });
      const previewMode = selectControl(state.previewMode, [['simultaneous', tx('全部可见内容同时更新', 'All visible cards simultaneously', 'Alle sichtbaren gleichzeitig')], ['bounded', tx('性能受限的分批更新', 'Performance-bounded batches', 'Leistungsgestaffelt')]], value => {
        state.previewMode = value; persistDiscoverState(); previewScheduler.refresh(); renderCurrentView();
      });
      const concurrency = selectControl(String(state.previewConcurrency), [['0', tx('所有可见内容', 'All visible', 'Alle sichtbaren')], ['1', '1'], ['2', '2'], ['4', '4'], ['6', '6'], ['8', '8'], ['12', '12'], ['16', '16'], ['24', '24']], value => {
        state.previewConcurrency = Number(value); persistDiscoverState(); previewScheduler.refresh();
      });
      const hoverEnabled = $('input', { type: 'checkbox', checked: state.hoverLivePreview });
      hoverEnabled.addEventListener('change', () => { state.hoverLivePreview = hoverEnabled.checked; persistDiscoverState(); previewScheduler.refresh(); });
      const hoverDelay = selectControl(String(state.hoverPreviewDelay), [['0', tx('立即', 'Immediately', 'Sofort')], ['150', '0,15 s'], ['250', '0,25 s'], ['400', '0,4 s'], ['600', '0,6 s'], ['1000', '1 s']], value => {
        state.hoverPreviewDelay = Number(value); persistDiscoverState(); previewScheduler.refresh();
      });
      const hoverScale = selectControl(String(state.hoverPreviewScale), [...new Set([100, 105, 110, 112, 115, 120, 125, 130, 135, 140, 150, 160, 170, 180, 200, 225, 250, 275, 300, 350, 400, 450, 500, 550, 600, state.hoverPreviewScale])].sort((a, b) => a - b).map(value => [String(value), `${value} %`]), value => {
        state.hoverPreviewScale = Number(value); persistDiscoverState(); previewScheduler.refresh();
      });
      const performance = $('details', { class: 'discover-details', open: homepage, dataset: { previewOptions: homepage ? 'homepage' : 'discover' } }, [
        $('summary', {}, tx('实时预览与性能', 'Live previews and performance', 'Live-Vorschau und Leistung')),
        $('div', { class: 'discover-filter-grid' }, [
          $('label', { class: 'discover-check', style: { alignSelf: 'end', minHeight: '38px' } }, [previewEnabled, tx('所有可见卡片的静音实时预览', 'Muted live preview for every visible card', 'Stumme Live-Vorschau für alle sichtbaren Karten')]),
          filterField(tx('更新率', 'Refresh rate', 'Aktualisierungsrate'), previewFps),
          filterField(tx('更新方式', 'Update mode', 'Aktualisierungsart'), previewMode),
          filterField(tx('分批并行限制', 'Batch concurrency limit', 'Parallelitätsgrenze bei Staffelung'), concurrency),
          $('label', { class: 'discover-check', style: { alignSelf: 'end', minHeight: '38px' } }, [hoverEnabled, tx('悬停时播放真正的实时视频', 'Real-time video while hovering', 'Echtes Livevideo beim Darüberfahren')]),
          filterField(tx('悬停延迟', 'Hover delay', 'Hover-Verzögerung'), hoverDelay),
          filterField(tx('悬停放大', 'Hover enlargement', 'Hover-Vergrößerung'), hoverScale),
        ]),
        $('p', { style: { margin: '9px 0 0', color: 'var(--dc-muted)', fontSize: '11px', lineHeight: '1.45' } }, tx(
          '可见卡片使用 JPEG 帧。鼠标悬停时，只有一张卡片切换到静音实时视频；移开鼠标后立即完全停止。高帧率会显著增加带宽和 CPU 使用。',
          'Visible cards use JPEG frames. On hover, only one card switches to muted real-time video and stops completely when the pointer leaves. High frame rates significantly increase bandwidth and CPU use.',
          'Sichtbare Karten verwenden JPEG-Einzelbilder. Beim Darüberfahren wechselt nur diese eine Karte auf ein stummes Echtzeitvideo und stoppt beim Verlassen vollständig. Hohe Bildraten – besonders ab 10 FPS – erhöhen Bandbreite und CPU-Last stark.'
        )),
      ]);
      performance.appendChild($('p', { class: 'discover-preview-size-note' }, tx('放大最大为 600%；实际显示会限制在窗口内。', 'Enlargement up to 600%; the displayed size is limited to the available viewport.', 'Vergrößerung bis 600 %; die tatsächliche Größe wird auf den verfügbaren Bildschirmplatz begrenzt.')));
      return performance;
    }

